def _pseudo_m(T):
    k = lambda s: f'<span class="kw">{s}</span>'
    c = lambda s: f'<span class="cm"># {s}</span>'
    return f"""{k(T("CONSTANTES de M1 e M2", "M1 and M2 CONSTANTS"))}   M_MAX = 5   BANDS_E = [0], [1], [2–3], [4–7], [8–15]   λ_RLS = 0.999   δ_RLS = 100
              EVERY = 8   CLIP_K = 2   N_MIN = 100   T_MAX = 5000   LAM = 0.99   SCALE_FLOOR = 0.1   ε_gate = 0.002   α_gate = 0.01

{k(T("PREVER", "PREDICT"))}(x_t):
  L ← {T("núcleo.prever", "core.predict")}(x_t)                              {c(T("pseudocódigo do núcleo acima", "core pseudocode above"))}
  {c(T("M1: especialista de precisão", "M1: precision expert"))}
  x ← {T("x_t com ausentes trocados pelo último valor visto", "x_t with missing values replaced by the last value seen")}
  z ← [1, ỹ_(t−1), ỹ_(t−2), {T("médias das BANDS_E das m = mín(d, M_MAX) entradas escolhidas, padronizadas", "BANDS_E means of the m = min(d, M_MAX) chosen inputs, standardised")}]
  E ← clip(w·z, L ± CLIP_K·max(σ̂_L, {T("piso", "floor")}))      {k(T("se", "if"))} {T("RLS determinada (n_RLS ≥ k = 3 + 5m)", "RLS determined (n_RLS ≥ k = 3 + 5m)")}
  L' ← L {k(T("se", "if"))} E {T("indefinido ou", "undefined or")} AdaHedge₁.n < N_MIN; {T("senão", "else")} (1 − ω)·L + ω·E      {c(T("sombra", "shadow"))}
  {c(T("M2: ponto de partida na referência trivial", "M2: start from the trivial reference"))}
  R ← 0 | y_last | y_(t−s)                                 {c(T("zero, persistência ou sazonal ingênuo, declarada", "zero, persistence or seasonal naive, declared"))}
  {k(T("se", "if"))} R {T("indefinida", "undefined")}: ŷ ← L'
  {T("senão", "else")}: H ← w_H·[R, L'];  W ← w_W·[R, L'];  s ← η·w_A / (η·w_A + w_B/2);  ŷ ← s·W + (1 − s)·H
  {k(T("retorna", "return"))} ŷ, [ŷ − q̂_o, ŷ + q̂_o]

{k(T("OBSERVAR", "OBSERVE"))}(y_t, quarantine):
  {T("núcleo.observar", "core.observe")}(y_t, quarantine)
  {k(T("se", "if"))} y_t {T("observado", "observed")}:
    AdaHedge₁.update((y_t − L)², (y_t − E)²)                  {c(T("erro quadrático sem recorte", "squared error, no clipping"))}
    learn ← ¬quarantine ∧ {T("entradas dentro do contrato", "inputs within the contract")}
    {k(T("se", "if"))} learn: {T("a cada EVERY alvos: triagem (médias exponenciais 1 − LAM) e RLS(z, y_t)", "every EVERY targets: screening (exponential means 1 − LAM) and RLS(z, y_t)")}
             {T("seleção das m entradas depois de N_MIN alvos e a cada T_MAX; se mudar: RLS e AdaHedge₁ recomeçam", "selection of the m inputs after N_MIN targets and every T_MAX; if it changes: RLS and AdaHedge₁ restart")}
    {k(T("se", "if"))} ¬quarantine ∧ R {T("definida", "defined")}:
      AdaHedge_H.update((y_t − R)², (y_t − L')²)
      s² ← max(min(σ̂²_R, σ̂²_L'), {T("piso", "floor")}²);  Switch_W.update((y_t − R)²/2s², (y_t − L')²/2s²)   {c(T("reserva em escala log contra 0/0", "log-scale fallback against 0/0"))}
      N ← max(LAM·N, (y_t − H)², (y_t − W)²);  Prod.update((y_t − H)²/N, (y_t − W)²/N)
      gate.observe(...)                                       {c(T("auditoria: registra eventos, não decide a saída", "audit: logs events, does not decide the output"))}
    {T("intervalo da saída", "output interval")}: miss ← |y_t − ŷ| > q̂_o;  {k(T("a cada", "every"))} EVERY: q̂_o ← max(0, q̂_o + 0.1·σ̂_o·Σ(miss − 0.1))"""


def sections(lang, N, Dg, G):
    P = lang == "pt"
    T = lambda pt, en: pt if P else en
    F = N["final"]; fam = F["fam"]; f6 = N["f6"]; dev = N["dev"]; val = N["val"]; sh = N["shocks"]; B = N["base"]
    FN = FAM[lang]; mn = MN[lang]

    def n(x, d=3):
        s = f"{x:,.{d}f}"
        return s.replace(",", "X").replace(".", ",").replace("X", ".") if P else s

    def ci(a):
        return "-" if not a else f"{n(a['geo'])} [{n(a['ic95'][0])}; {n(a['ic95'][1])}]"

    def ci_s(s):
        lo, hi = (float(v) for v in s.strip("[]").split(","))
        return f"[{n(lo)}; {n(hi)}]"

    def tbl(head, rows, cls="compact", hl=None):
        h = "".join(f"<th>{c}</th>" for c in head)
        body = "".join(('<tr class="highlight-row">' if hl and hl(r) else "<tr>") + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
        return f'<table class="no-break {cls}"><thead><tr>{h}</tr></thead><tbody>{body}</tbody></table>'

    def fig(s, cap):
        return f'<div class="diagram-container no-break">{s}<div class="diagram-caption">{cap}</div></div>'

    # ---------------- numbers of the whole LEBRE (final evaluation)
    ov = F["overall"]
    inc_med, inc_max = float(np.median(F["inc_all"])), float(max(F["inc_all"]))
    c_med, c_max, c_min = float(np.median(F["cost_all"])), float(max(F["cost_all"])), float(min(F["cost_all"]))
    cc_med = float(np.median(F["core_cost_all"]))
    nm = F["ram_info"]["numeros_m1"] + F["ram_info"]["numeros_m2"]
    core_bytes = F["ram"] - 8 * nm
    ch53 = {k: fam[k]["chronos53"] for k in FAMS}
    # ---------------- numbers of the structural core (its own evaluations)
    t3, p3, pf, r3m = B["r3_tab"], B["r3_pair"], B["r3_pair_fm"], B["r3_meta"]
    t2, t1, mcu = B["r2_tab"], B["r1_tab"], B["mcu"]
    g1 = B["r3p_gm"]
    fp3 = float(r3m.fp.mean()); fpmax3 = float(r3m.fp_max.max())
    ttm0, ttm1 = B["ttm_flops"]
    imin, imax = float(mcu["mean"].min()), float(mcu["mean"].max())
    us = lambda i: i * 1.6 / 168
    eq_dev = B["equiv"]; n_eq_dev = int(eq_dev.events_equal_f32.sum()); n_eq_dev64 = int(eq_dev.events_equal_f64.sum())
    n_eq_r3 = int(r3m.c32_events_equal.sum())
    ab = B["abl"].loc["r2+r3"]; fs = B["fdr_sum"]; fr = B["fdr_runs"]
    fall = fs[fs.rho == "all"].set_index("scen")
    fcell = lambda sc, r: fs[(fs.scen == sc) & (fs.rho == str(r))].iloc[0]
    n_null = int(fr[fr.scen.str.startswith("N")].shape[0]); v_null = int((fr[fr.scen.str.startswith("N")].V > 0).sum())
    n_prox = int((fr.V > 0).sum()); n_rem = int(((fr.V > 0) & ~fr.final_false).sum()); n_fin = int(fr.final_false.sum())
    lebre_ci = lambda: ci_s(t3.loc["V052_PY", "CI95"])

    toc = [T("Sumário executivo", "Executive summary"), T("O problema, a premissa e o escopo", "The problem, the premise and the scope"),
           T("Princípios de projeto", "Design principles"), T("Visão geral da arquitetura", "Architecture overview"),
           T("Base teórica do núcleo estrutural", "Theoretical basis of the structural core"),
           T("Base teórica de M1 e M2: agregação de previsores", "Theoretical basis of M1 and M2: aggregation of forecasters"),
           T("Ciclo de vida de uma mudança de estrutura", "Lifecycle of a structural change"),
           T("A condição de uso: desajuste da referência", "The condition of use: reference misadjustment"),
           T("M1: especialista de precisão", "M1: precision expert"), T("M2: ponto de partida na referência trivial", "M2: starting from the trivial reference"),
           T("Salvaguardas de saída e intervalo", "Output safeguards and interval"), T("Custo computacional e memória", "Computational cost and memory"),
           T("Observabilidade e explicabilidade", "Observability and explainability"), T("Metodologia de avaliação", "Evaluation methodology"),
           T("Evidência do núcleo estrutural", "Evidence for the structural core"),
           T("O núcleo em microcontrolador simulado", "The core on a simulated microcontroller"),
           T("Desenvolvimento de M1 e M2", "Development of M1 and M2"), T("Validações em dados novos", "Validations on new data"),
           T("Avaliação final pré-registrada", "Pre-registered final evaluation"), T("Evolução da arquitetura e ablações", "Evolution of the architecture and ablations"),
           T("Posição na literatura", "Position in the literature"), T("Limites e afirmações que não fazemos", "Limits and claims we do not make"),
           T("Parâmetros", "Parameters"), T("Pseudocódigo e condições de reprodutibilidade", "Pseudocode and reproducibility conditions"),
           T("Referências", "References"), T("Histórico de revisões", "Revision history")]
    tl = "".join(f'<li class="toc-item"><span class="toc-title">{i + 1}. {t}</span><span class="toc-page">§{i + 1}</span></li>' for i, t in enumerate(toc))
    out = [f"""<div class="page-break"></div><h1>{T("Sumário", "Contents")}</h1><ul class="toc-list">{tl}</ul>"""]

    # ------------------------------------------------------------ 1 executive summary
    gains = ", ".join(f"{FN[k]} {n(fam[k]['ratio'])}" for k in ("camels", "fx_niv", "fx_ret", "bdg2"))
    out.append(f"""<div class="page-break"></div><h1>1. {toc[0]}</h1>
<p>{T(f"A <strong>LEBRE</strong> é um previsor <strong>online</strong> de séries temporais com entradas: a cada passo ela recebe as entradas e, quando disponível, o valor do alvo; prevê o próximo valor, aprende com o erro e segue, sem reprocessar o passado e sem treino prévio. O custo por passo é fixo, dado o número de entradas, e é contado operação a operação: nas {F['n']} séries da avaliação final, mediana de {n(c_med, 0)} e máximo de {n(c_max, 0)} operações de ponto flutuante por passo.",
f"<strong>LEBRE</strong> is an <strong>online</strong> forecaster for time series with inputs: at every step it receives the inputs and, when available, the target value; it predicts the next value, learns from the error and moves on, without re-processing the past and without prior training. The per-step cost is fixed, given the number of inputs, and is counted operation by operation: over the {F['n']} series of the final evaluation, a median of {n(c_med, 0)} and a maximum of {n(c_max, 0)} floating-point operations per step.")}</p>
<p>{T("Ela tem três camadas (§4). O <strong>núcleo estrutural</strong> é um modelo vivo simples (uma memória do próprio alvo e uma regressão linear nas entradas) cuja estrutura só muda por experimento: um desafiante em sombra propõe acrescentar, remover, trocar ou refinar a resposta a uma entrada inteira, e a mudança só é aceita quando um <em>e-process</em> — um teste sequencial válido a qualquer momento — acumula evidência suficiente de melhora preditiva, dentro de um procedimento online de multiplicidade. A <strong>M1</strong> combina a previsão do núcleo com um especialista de precisão (uma regressão recursiva sobre o passado do alvo e médias de defasagem das entradas). A <strong>M2</strong> faz a previsão partir de uma referência trivial declarada (zero, persistência ou sazonal ingênuo) e só confiar na parte adaptativa quando ela se mostra melhor. Nenhuma dessas peças é nova isoladamente; o documento descreve a combinação, as condições em que ela funciona e o que foi medido.",
"It has three layers (§4). The <strong>structural core</strong> is a simple live model (a memory of the target itself and a linear regression on the inputs) whose structure only changes by experiment: a challenger in shadow proposes to add, remove, swap or refine the response to a whole input, and the change is only accepted when an <em>e-process</em> — a sequential test valid at any time — accrues enough evidence of predictive improvement, within an online multiple-testing procedure. <strong>M1</strong> combines the core forecast with a precision expert (a recursive regression on the target's past and on lag-band means of the inputs). <strong>M2</strong> makes the forecast start from a declared trivial reference (zero, persistence or seasonal naive) and trust the adaptive part only when it proves better. None of these parts is new in isolation; the document describes the combination, the conditions under which it works and what was measured.")}</p>
<div class="alert alert-warning"><strong>{T("Premissa", "Premise")}:</strong> {T("a LEBRE <strong>não pretende ser o previsor mais preciso</strong>. O objetivo é entregar previsões úteis, sem falhas graves, com custo por passo baixo e previsível, sem ajuste por série e com cada mudança de estrutura registrada e justificada. Modelos caros são tratados como <strong>tetos de referência</strong>, não como adversários.",
"LEBRE <strong>does not aim to be the most accurate forecaster</strong>. The goal is to deliver useful forecasts, without severe failures, at a low and predictable per-step cost, without per-series tuning and with every structural change logged and justified. Expensive models are treated as <strong>reference ceilings</strong>, not as opponents.")}</div>
<div class="alert alert-info"><strong>{T("O que foi medido", "What was measured")}</strong>
<ul style="margin-top:4px">
<li>{T(f"<strong>Avaliação final pré-registrada</strong> ({F['n']} séries reservadas antes de qualquer código de M1 e M2; bacias, prédios, usinas solares e eólicas, carga elétrica e câmbio): o erro quadrático médio da LEBRE dividido pelo do núcleo sozinho foi", f"<strong>Pre-registered final evaluation</strong> ({F['n']} series reserved before any M1 and M2 code; basins, buildings, solar and wind plants, electric load and FX): LEBRE's mean squared error divided by that of the core alone was")} <strong>{n(ov['geo'])}</strong> [{T('IC 95%', '95% CI')} {n(ov['ic95'][0])}; {n(ov['ic95'][1])}], {T("sem piora em nenhuma família; o ganho vem de", "with no harm in any family; the gain comes from")} {gains}; {T("em solar, eólica e carga, a LEBRE é idêntica ao núcleo (§19).", "in solar, wind and load, LEBRE is identical to the core (§19).")}</li>
<li>{T(f"<strong>Tetos de referência</strong> na mesma avaliação: contra o Chronos-2 com covariáveis (modelo de fundação de ~10⁹ operações por previsão), razão de {n(min(ch53.values()), 2)} a {n(max(ch53.values()), 2)} por família — menor que 1 em bacias e câmbio, maior em prédios, solar, eólica e carga (§19).", f"<strong>Reference ceilings</strong> in the same evaluation: against Chronos-2 with covariates (a foundation model of ~10⁹ operations per forecast), a ratio of {n(min(ch53.values()), 2)} to {n(max(ch53.values()), 2)} per family — below 1 in basins and FX, above in buildings, solar, wind and load (§19).")}</li>
<li>{T(f"<strong>O núcleo na sua classe de orçamento</strong> (avaliação pré-registrada própria, 60 séries de bacias e prédios): erro relativo ao NLinear online de {n(t3.loc['V052_PY', 'ALL'])} {lebre_ci()}, o menor entre os oito comparadores de custo semelhante avaliados, sem nenhuma série com falha grave; empate com um SARIMAX com entradas e erro ~25% maior que o do Chronos-2 (§15).", f"<strong>The core in its budget class</strong> (its own pre-registered evaluation, 60 basin and building series): error relative to online NLinear of {n(t3.loc['V052_PY', 'ALL'])} {lebre_ci()}, the lowest among the eight comparators of similar cost evaluated, with no series with a severe failure; a tie with a SARIMAX with inputs and ~25% higher error than Chronos-2 (§15).")}</li>
<li>{T(f"<strong>Custo:</strong> M1 e M2 acrescentam ao núcleo uma mediana de {n(inc_med, 0)} operações por passo (máximo {n(inc_max, 0)}; teto pré-registrado de 1.100); memória estimada de {n(F['ram'] / 1024, 1)} KB. O núcleo, portado para C, rodou num Cortex-M4F <strong>simulado</strong> com {n(imin / 1000, 1)}–{n(imax / 1000, 1)} mil instruções por passo em média; M1 e M2 não foram portados (§12, §16).", f"<strong>Cost:</strong> M1 and M2 add to the core a median of {n(inc_med, 0)} operations per step (maximum {n(inc_max, 0)}; pre-registered ceiling 1,100); estimated memory {n(F['ram'] / 1024, 1)} KB. The core, ported to C, ran on a <strong>simulated</strong> Cortex-M4F at {n(imin / 1000, 1)}–{n(imax / 1000, 1)} thousand instructions per step on average; M1 and M2 were not ported (§12, §16).")}</li></ul></div>
<div class="alert alert-danger"><strong>{T("Limites principais:", "Main limits:")}</strong> {T(f"previsão de um passo; M1 e M2 custam em todas as séries e só ganham em parte dos domínios; o mecanismo de testes do núcleo <strong>não melhorou a precisão</strong> em relação a ligar todas as entradas sem testes (razão {n(ab['ratio'])} [{n(ab['lo'])}; {n(ab['hi'])}] em 100 séries, exploratório) — o seu papel é produzir estrutura registrada, cuja utilidade prática não foi demonstrada; entradas correlacionadas com a verdadeira podem ser aceitas como substitutas; não há garantia formal de erro na escala original para M1 e M2; o microcontrolador foi simulado e só para o núcleo. Nenhum componente é original (§21, §22).",
f"one-step forecasting; M1 and M2 cost on every series and only gain in part of the domains; the core's testing mechanism <strong>did not improve accuracy</strong> compared to switching all inputs on without tests (ratio {n(ab['ratio'])} [{n(ab['lo'])}; {n(ab['hi'])}] on 100 series, exploratory) — its role is to produce a logged structure, whose practical usefulness was not demonstrated; inputs correlated with the true one may be accepted as substitutes; there is no formal error guarantee in the original scale for M1 and M2; the microcontroller was simulated and only for the core. No component is original (§21, §22).")}</div>
""")

    # ------------------------------------------------------------ 2 problem
    out.append(f"""<div class="page-break"></div><h1>2. {toc[1]}</h1>
<h2>{T("O problema", "The problem")}</h2>
<p>{T("Muitos sistemas medem continuamente um alvo (vazão de um rio, consumo de um prédio, geração de uma usina, carga elétrica, uma taxa de câmbio) junto com entradas que o influenciam, muitas vezes com atraso (chuva, temperatura, vazões a montante, outras moedas). Prever o próximo valor <em>no próprio dispositivo</em> exige três coisas ao mesmo tempo: custo por passo muito baixo, funcionamento sem ajuste por série e sem treino prévio, e um comportamento que não falhe de forma grave quando o fluxo tem lacunas, mudanças ou é quase imprevisível. Os modelos modernos mais precisos (modelos de fundação) custam de 10⁷ a 10¹⁰ operações por previsão; os modelos clássicos ajustados série a série precisam de otimização por máxima verossimilhança; e os modelos lineares online baratos não sabem, sozinhos, quais entradas e atrasos importam, nem quando é melhor não arriscar nada além de uma previsão trivial.",
"Many systems continuously measure a target (river flow, building consumption, plant generation, electric load, an exchange rate) together with inputs that influence it, often with delay (rain, temperature, upstream flows, other currencies). Forecasting the next value <em>on the device itself</em> requires three things at once: very low per-step cost, operation without per-series tuning or prior training, and a behaviour that does not fail severely when the stream has gaps, changes or is nearly unpredictable. The most accurate modern models (foundation models) cost 10⁷ to 10¹⁰ operations per forecast; classical models fitted series by series need maximum-likelihood optimisation; and cheap online linear models do not know, by themselves, which inputs and delays matter, nor when it is better to risk nothing beyond a trivial forecast.")}</p>
<h2>{T("A premissa", "The premise")}</h2>
<p>{T("A LEBRE ocupa um ponto específico do compromisso entre precisão, custo e transparência. Ela é avaliada <strong>dentro da sua classe de orçamento</strong> (modelos com até ~10⁴ operações por previsão), com os modelos caros como tetos. “Entregar bem” significa: erro competitivo na classe, <strong>nenhuma falha catastrófica</strong>, não perder para uma previsão trivial declarada, custo previsível e explicação de cada mudança.",
"LEBRE occupies a specific point of the accuracy–cost–transparency trade-off. It is evaluated <strong>within its budget class</strong> (models with up to ~10⁴ operations per forecast), with the expensive models as ceilings. “Delivering well” means: competitive error within the class, <strong>no catastrophic failure</strong>, not losing to a declared trivial forecast, predictable cost and an explanation of every change.")}</p>
<h2>{T("Escopo", "Scope")}</h2>
<ul><li>{T("previsão de <strong>um passo à frente</strong>, online, com as entradas do instante atual disponíveis (como em controle e em previsão de curtíssimo prazo);", "<strong>one-step-ahead</strong> forecasting, online, with the current inputs available (as in control and very-short-term forecasting);")}</li>
<li>{T("séries com <strong>poucas entradas</strong> e relação aproximadamente linear, com atrasos de até 31 passos no núcleo e até 15 no especialista de precisão;", "series with <strong>few inputs</strong> and an approximately linear relation, with delays of up to 31 steps in the core and up to 15 in the precision expert;")}</li>
<li>{T("o ambiente informa apenas o período de amostragem (por exemplo, 24 para dados horários com ciclo diário; nos prédios, também 168 para o ciclo semanal) e a referência trivial adequada ao alvo (zero para variações como retornos financeiros, sazonal ingênuo quando há ciclo, persistência nos demais casos);", "the environment only provides the sampling period (e.g. 24 for hourly data with a daily cycle; for buildings, also 168 for the weekly cycle) and the trivial reference suited to the target (zero for changes such as financial returns, seasonal naive when there is a cycle, persistence otherwise);")}</li>
<li>{T("entradas padronizadas de forma causal (média e variância exponenciais), como contrato de entrada.", "inputs standardised causally (exponential mean and variance), as an input contract.")}</li></ul>
<h2>{T("O que a LEBRE não é", "What LEBRE is not")}</h2>
<p>{T("Não é um modelo de fundação nem um previsor de longo horizonte; não modela relações fortemente não lineares; não afirma causalidade física (uma entrada aceita é uma entrada com <em>relevância preditiva</em> certificada contra a referência, e entradas quase idênticas são reportadas como grupo). O nome vem da família original de arquiteturas do projeto (<em>Lifecycle-governed Evidence-Based Resource Evolution</em>): estrutura que entra e sai do modelo por evidência, dentro de um orçamento.",
"It is not a foundation model nor a long-horizon forecaster; it does not model strongly non-linear relations; it does not claim physical causality (an accepted input is an input with certified <em>predictive relevance</em> against the reference, and near-identical inputs are reported as a group). The name comes from the project's original family of architectures (<em>Lifecycle-governed Evidence-Based Resource Evolution</em>): structure that enters and leaves the model by evidence, within a budget.")}</p>""")

    # ------------------------------------------------------------ 3 principles, 4 architecture
    pr = [(T("Toda mudança de estrutura é um experimento", "Every structural change is an experiment"), T("A estrutura só muda quando um teste sequencial sempre válido rejeita “a mudança não melhora a previsão”; cada aceitação tem um nível de erro fixado antes.", "Structure only changes when an anytime-valid sequential test rejects “the change does not improve the forecast”; each acceptance has an error level fixed beforehand.")),
          (T("Unidade = uma entrada inteira", "Unit = a whole input"), T("A pergunta é “esta entrada ajuda?”, e não “este atraso ajuda?”: menos hipóteses, mais poder, resposta refinada depois por divisões hierárquicas.", "The question is “does this input help?”, not “does this lag help?”: fewer hypotheses, more power, the response being refined later by hierarchical splits.")),
          (T("Partir do trivial", "Start from the trivial"), T("A previsão final parte de uma referência trivial declarada e só passa a confiar na parte adaptativa quando ela se mostra melhor nos próprios dados.", "The final forecast starts from a declared trivial reference and only comes to trust the adaptive part when it proves better on the data themselves.")),
          (T("Camadas que não mexem no núcleo", "Layers that do not touch the core"), T("M1 e M2 só mudam como a previsão final é formada; as decisões de estrutura são as mesmas com ou sem elas (verificado em todas as séries avaliadas).", "M1 and M2 only change how the final forecast is formed; the structural decisions are the same with or without them (verified on every evaluated series).")),
          (T("Custo fixo e declarado", "Fixed, declared cost"), T("Custo por passo fixo dado o número de entradas, contado operação a operação, com limites declarados antes de cada avaliação; o resultado é reportado mesmo quando o limite não é cumprido (§12).", "Fixed per-step cost given the number of inputs, counted operation by operation, with limits declared before each evaluation; the result is reported even when the limit is not met (§12).")),
          (T("Sem ajuste por série", "No per-series tuning"), T("As mesmas constantes em qualquer série; o ambiente informa só o(s) período(s) e a referência trivial.", "The same constants on any series; the environment only provides the period(s) and the trivial reference.")),
          (T("Silêncio e dados fora do contrato não são evidência", "Silence and out-of-contract data are not evidence"), T("Sem alvo observado, com entrada recortada (|x| > 8σ) ou em quarentena, nada da estrutura aprende e nenhuma evidência é acumulada.", "Without an observed target, with a clipped input (|x| > 8σ) or in quarantine, nothing in the structure learns and no evidence accrues.")),
          (T("Saída dentro de contrato", "Output within contract"), T("A previsão do núcleo nunca sai de um envelope dos valores já observados, e lacunas do alvo não fecham a malha da memória.", "The core forecast never leaves an envelope of already observed values, and target gaps do not close the memory loop.")),
          (T("Observabilidade", "Observability"), T("Cada mudança é registrada com instante, tipo, evidência e grupo de entradas equivalentes; os pesos de M1 e M2 são legíveis a cada passo; a previsão vem com intervalo adaptativo.", "Every change is logged with time, kind, evidence and group of equivalent inputs; the weights of M1 and M2 are readable at every step; the forecast comes with an adaptive interval."))]
    out.append(f"""<h1>3. {toc[2]}</h1>
{tbl([T('Princípio', 'Principle'), T('Significado', 'Meaning')], [(f'<strong>{a}</strong>', b) for a, b in pr])}
<div class="page-break"></div><h1>4. {toc[3]}</h1>
{fig(Dg['arch'], T("Visão completa de um passo de previsão. O núcleo roda inteiro por baixo; M1 forma L' a partir de L; M2 forma a saída a partir de L' e da referência R.", "Complete view of one forecasting step. The core runs entirely underneath; M1 forms L' from L; M2 forms the output from L' and the reference R."))}
<p>{T("A LEBRE tem três camadas, executadas nesta ordem a cada passo:", "LEBRE has three layers, executed in this order at every step:")}</p>
<ol><li>{T("<strong>Núcleo estrutural</strong> (D2): produz a previsão L e é o único dono das mudanças de estrutura. Tem dois especialistas e uma combinação no caminho da previsão, e um plano de mudanças em sombra.", "<strong>Structural core</strong> (D2): produces the forecast L and is the only owner of structural changes. It has two experts and a combination on the forecast path, and a change plane in shadow.")}</li>
<li>{T("<strong>M1 — especialista de precisão</strong> (§9): uma regressão recursiva E sobre o passado do alvo e médias de defasagem das entradas mais correlacionadas, combinada com L por AdaHedge no erro quadrático: L' = (1 − ω)·L + ω·E. Onde E não ajuda, ω vai a zero e L' = L.", "<strong>M1 — precision expert</strong> (§9): a recursive regression E on the target's past and on lag-band means of the most correlated inputs, combined with L by AdaHedge on the squared error: L' = (1 − ω)·L + ω·E. Where E does not help, ω goes to zero and L' = L.")}</li>
<li>{T("<strong>M2 — ponto de partida na referência trivial</strong> (§10): mistura R e L' por dois caminhos — H, conservador (AdaHedge), e W, que troca de R para L' uma única vez (switch distribution) — e combina os dois por um (A,B)-Prod, que garante não ficar muito atrás de H.", "<strong>M2 — starting from the trivial reference</strong> (§10): mixes R and L' through two paths — H, conservative (AdaHedge), and W, which switches from R to L' once (switch distribution) — and combines both with an (A,B)-Prod, which guarantees not falling far behind H.")}</li></ol>
{fig(Dg['core'], T('Núcleo estrutural. Os dois especialistas e a combinação formam o caminho da previsão L. O plano de mudanças roda em sombra e só altera S quando uma mudança é aceita.', 'Structural core. The two experts and the combination form the path of the forecast L. The change plane runs in shadow and only alters S when a change is accepted.'))}
<p>{T("<strong>Memória (M).</strong> Prevê o alvo a partir do seu próprio passado, relativo ao último valor: reversão a uma média lenta, última diferença, termos sazonais do(s) ciclo(s) declarado(s) e um perfil de incrementos por fase do ciclo. <strong>Especialista estrutural (S).</strong> Regressão linear no valor atual de cada entrada (a “base”) mais os <em>blocos de resposta</em> das unidades aceitas. <strong>Combinação.</strong> Média dinâmica de modelos entre M e S, com peso que acompanha qual dos dois vem errando menos. <strong>Plano de mudanças.</strong> Uma triagem barata aponta a candidata mais promissora; até dois experimentos rodam em sombra; um e-process acumula a evidência de cada mudança; um procedimento de níveis online decide.",
"<strong>Memory (M).</strong> Predicts the target from its own past, relative to the last value: reversion to a slow mean, the last difference, seasonal terms of the declared cycle(s) and a profile of increments per cycle phase. <strong>Structural expert (S).</strong> Linear regression on the current value of each input (the “base”) plus the <em>response blocks</em> of the accepted units. <strong>Combination.</strong> Dynamic model averaging between M and S, with a weight that follows which of the two has been erring less. <strong>Change plane.</strong> A cheap screen points to the most promising candidate; up to two experiments run in shadow; an e-process accrues the evidence of each change; an online level procedure decides.")}</p>
{fig(Dg['step'], T('Ordem das operações num passo. A previsão em t é emitida antes de y(t) ser lido; M1 e M2 aprendem depois do núcleo, com o mesmo y(t).', 'Order of operations in one step. The forecast at t is issued before y(t) is read; M1 and M2 learn after the core, with the same y(t).'))}""")

    # ------------------------------------------------------------ 5 core theory (5.1–5.5)
    out.append(f"""<h1>5. {toc[4]}</h1>
<p>{T("Esta seção reúne a base teórica do núcleo. <strong>Todas as ferramentas vêm da literatura</strong> (citada em cada item); o que é específico da LEBRE é a forma de combiná-las e as condições de uso verificadas (§8).", "This section gathers the theoretical basis of the core. <strong>All tools come from the literature</strong> (cited in each item); what is specific to LEBRE is the way they are combined and the verified conditions of use (§8).")}</p>
<h2>5.1 {T("Aprendizado linear online: NLMS e mínimos quadrados recursivos", "Online linear learning: NLMS and recursive least squares")}</h2>
<p>{T("O modelo vivo (base de S, pesos dos blocos e memória) aprende por <strong>NLMS</strong> (mínimos quadrados médios normalizados; Widrow & Stearns 1985; Haykin 2002):", "The live model (base of S, block weights and memory) learns by <strong>NLMS</strong> (normalised least mean squares; Widrow & Stearns 1985; Haykin 2002):")}</p>
<div class="math-box">$$w_{{t+1}} = w_t + ¤mu¤,¤frac{{e_t}}{{¤lVert ¤phi_t¤rVert^2 + ¤delta}}¤,¤phi_t,¤qquad e_t = y_t - w_t^¤top¤phi_t .$$
{T("Em regime estacionário, o <strong>desajuste</strong> (excesso relativo de erro quadrático por causa da oscilação dos pesos) é aproximadamente", "In steady state, the <strong>misadjustment</strong> (relative excess squared error caused by the weight jitter) is approximately")} ¤(M ¤approx ¤mu/(2-¤mu)¤). {T("O núcleo usa μ = 0,05 em S e na memória.", "The core uses μ = 0.05 in S and in the memory.")}</div>
<p>{T("Os <strong>desafiantes</strong> usam mínimos quadrados recursivos (RLS) sem esquecimento dentro de cada episódio, com ¤(P_0 = 10¤,I¤): com poucos parâmetros (5 a 7), o RLS converge em dezenas de amostras e dá um coeficiente praticamente constante no episódio, o que importa para a condição de uso (§8). O especialista de precisão da M1 também usa RLS, com esquecimento (§9).", "The <strong>challengers</strong> use recursive least squares (RLS) without forgetting within each episode, with ¤(P_0 = 10¤,I¤): with few parameters (5 to 7), RLS converges in tens of samples and gives an almost constant coefficient within the episode, which matters for the condition of use (§8). M1's precision expert also uses RLS, with forgetting (§9).")}</p>
<h2>5.2 {T("Memória: suavização exponencial em forma de regressão", "Memory: exponential smoothing in regression form")}</h2>
<p>{T("A memória é uma regressão do incremento sobre atributos do próprio passado, inspirada no modelo <em>airline</em> (Box & Jenkins 1970) e no estado sazonal do Holt-Winters (Hyndman et al. 2008) — analogia, não equivalência:", "The memory is a regression of the increment on features of its own past, inspired by the <em>airline</em> model (Box & Jenkins 1970) and by the Holt-Winters seasonal state (Hyndman et al. 2008) — an analogy, not an equivalence:")}</p>
<div class="math-box">$$¤begin{{aligned}}¤hat y^M_t = y_{{t-1}} &+ w_1(m_t - y_{{t-1}}) + w_2(y_{{t-1}}-y_{{t-2}}) + w_3(y_{{t-s}}-y_{{t-1}}) + w_4(y_{{t-s+1}}-y_{{t-s}}) + w_5 G_{{t ¤bmod s}}¤¤ &+¤,[¤,w_6(y_{{t-s_2}}-y_{{t-1}}) + w_7(y_{{t-s_2+1}}-y_{{t-s_2}})¤,]¤end{{aligned}}$$
{T("m: média exponencial lenta (taxa 0,01); G: média exponencial (taxa 0,1) dos incrementos observados na mesma fase do ciclo; s₂: segundo ciclo declarado (semana, nos prédios). A normalização do NLMS tem pisos relativos à escala (10⁻³ da potência média dos atributos e 10⁻⁴ da escala lenta de y), para que trechos planos não produzam passos enormes.", "m: slow exponential mean (rate 0.01); G: exponential mean (rate 0.1) of the increments observed at the same cycle phase; s₂: second declared cycle (week, for buildings). The NLMS normalisation has scale-relative floors (10⁻³ of the mean feature power and 10⁻⁴ of the slow scale of y), so that flat stretches do not produce huge steps.")}</div>
<h2>5.3 {T("Combinação no núcleo: média dinâmica de modelos", "Combination in the core: dynamic model averaging")}</h2>
<p>{T("O peso de S segue a diferença descontada de perdas entre os dois especialistas (Raftery, Kárný & Ettler 2010; forma logística equivalente a pesos exponenciais de especialistas):", "The weight of S follows the discounted loss difference between the two experts (Raftery, Kárný & Ettler 2010; a logistic form equivalent to exponential expert weights):")}</p>
<div class="math-box">$$D_t = 0.99¤,D_{{t-1}} + ¤frac{{(y_t-¤hat y^S_t)^2 - (y_t-¤hat y^M_t)^2}}{{¤hat¤sigma^2}},¤qquad w_S = ¤frac{{1}}{{1+e^{{¤,0.5¤,D_t}}}},¤qquad L_t = ¤hat y^M_t + w_S(¤hat y^S_t-¤hat y^M_t).$$</div>
<h2>5.4 {T("Representação da resposta: faixas de oitava, atraso de pico e divisões de Haar", "Response representation: octave bands, peak lag and Haar splits")}</h2>
<p>{T("A resposta de uma entrada é aproximada por médias do seu passado em faixas diádicas [1], [2–3], [4–7], [8–15], [16–31] — uma resolução que diminui com o atraso, como nas decomposições em multirresolução (Mallat 1989) e nos modelos de defasagem distribuída. Uma média de faixa dilui um atraso isolado (retém ~1/largura do efeito); por isso o desafiante carrega também o seu <strong>atraso de pico</strong> k*, escolhido por ele mesmo pela maior correlação pré-branqueada nas primeiras 200 amostras do aquecimento — antes de qualquer evidência, o que mantém o desafiante previsível. Depois da aceitação, cada faixa pode ser <strong>dividida</strong> nas duas metades (um coeficiente de Haar); cada divisão é uma nova hipótese, testada só se o “pai” foi aceito, no espírito do teste hierárquico (Meinshausen 2008; Yekutieli 2008).",
"The response of an input is approximated by means of its past over dyadic bands [1], [2–3], [4–7], [8–15], [16–31] — a resolution that decreases with delay, as in multiresolution decompositions (Mallat 1989) and distributed-lag models. A band mean dilutes an isolated delay (it keeps ~1/width of the effect); therefore the challenger also carries its <strong>peak lag</strong> k*, chosen by itself as the largest prewhitened correlation in the first 200 samples of the warm-up — before any evidence, which keeps the challenger predictable. After acceptance, each band may be <strong>split</strong> into its two halves (one Haar coefficient); each split is a new hypothesis, tested only if the “parent” was accepted, in the spirit of hierarchical testing (Meinshausen 2008; Yekutieli 2008).")}</p>
{fig(Dg['unit'], T('Representação da resposta a uma entrada: médias em faixas de oitava, o valor atual e um atraso de pico; depois da aceitação, cada faixa pode ser dividida em metades, uma hipótese por divisão.', 'Representation of the response to an input: means over octave bands, the current value and a peak lag; after acceptance, each band may be split into halves, one hypothesis per split.'))}
<h2>5.5 {T("Triagem: pré-branqueamento e estatística de grupo", "Screening: prewhitening and group statistic")}</h2>
<p>{T("Para escolher a próxima candidata sem testar todas, cada entrada inativa tem uma estatística de grupo: correlações exponenciais (peso 0,02) entre o resíduo de S e as médias de faixa, ambos <strong>pré-branqueados</strong> por um AR(1) causal da entrada (Box & Jenkins 1970), somadas em quadrado e normalizadas pela variância nula. A unidade é aberta se a estatística passa do quantil 99% de χ²₅ (15,09); uma divisão, do quantil 99% de χ²₁ (6,63), sobre o detalhe de Haar. A triagem <strong>não gera evidência</strong>: ela só escolhe o que testar, e o controle de erro vem inteiro do e-process.",
"To choose the next candidate without testing them all, each inactive input has a group statistic: exponential correlations (weight 0.02) between the residual of S and the band means, both <strong>prewhitened</strong> by a causal AR(1) of the input (Box & Jenkins 1970), squared, summed and normalised by the null variance. The unit is opened if the statistic exceeds the 99% quantile of χ²₅ (15.09); a split, the 99% quantile of χ²₁ (6.63), on the Haar detail. The screen <strong>produces no evidence</strong>: it only chooses what to test, and the error control comes entirely from the e-process.")}</p>""")

    # ------------------------------------------------------------ 5.6–5.8
    out.append(f"""<h2>5.6 {T("Evidência sempre válida: e-processes de melhora preditiva", "Anytime-valid evidence: e-processes of predictive improvement")}</h2>
<p>{T("Um <strong>e-process</strong> é um processo não negativo cuja esperança, sob a hipótese nula, não passa de 1 em nenhum tempo de parada; por Ville, a probabilidade de ele alguma vez ultrapassar 1/α é ≤ α. Isso permite olhar a evidência a cada passo, pausar e retomar sem inflar o erro (Ramdas, Grünwald, Vovk & Shafer 2023; Grünwald, de Heide & Koolen 2024). O núcleo usa a comparação sequencial de previsores de Choe & Ramdas (2024), com a nula <em>fraca</em>: em média, o desafiante não melhora a perda da referência em mais que uma margem ε.",
"An <strong>e-process</strong> is a non-negative process whose expectation under the null does not exceed 1 at any stopping time; by Ville's inequality, the probability that it ever exceeds 1/α is ≤ α. This allows looking at the evidence at every step, pausing and resuming without inflating the error (Ramdas, Grünwald, Vovk & Shafer 2023; Grünwald, de Heide & Koolen 2024). The core uses the sequential comparison of forecasters of Choe & Ramdas (2024), with the <em>weak</em> null: on average, the challenger does not improve the loss of the reference by more than a margin ε.")}</p>
<div class="math-box">{T("Perda recortada e diferencial, com a escala", "Clipped loss and differential, with the scale")} ¤(B_t = 2¤max(¤hat¤sigma^S_t,¤;0.1¤,s^{{lenta}}_t)¤):
$$¤ell_t(u) = ¤min¤{{(y_t-u)^2/B_t^2,¤;1¤}},¤qquad d_t = ¤ell_t(¤hat y^S_t) - ¤ell_t(g_t) - ¤varepsilon .$$
{T("E-process de mistura sub-exponencial, com centragem previsível", "Sub-exponential mixture e-process, with predictable centring")} ¤(¤gamma_i=¤min(¤bar d_{{i-1}},0)¤) {T("e 8 valores de λ", "and 8 values of λ")}:
$$E_n = ¤frac18¤sum_{{j=0}}^{{7}}¤exp¤Big¤{{¤lambda_j¤sum_{{i¤le n}} d_i - ¤psi_{{E,c}}(¤lambda_j)¤sum_{{i¤le n}}(d_i-¤gamma_i)^2¤Big¤}},¤quad ¤psi_{{E,c}}(¤lambda)=¤frac{{-¤log(1-c¤lambda)-c¤lambda}}{{c^2}},¤quad ¤lambda_j=¤frac{{0.9¤cdot 2^{{-j}}}}{{c}} .$$</div>
<p>{T("<strong>A constante c unilateral.</strong> O enunciado de Choe & Ramdas supõe |d_i − γ_i| ≤ c, o que daria c = 2(1+|ε|). A demonstração de base (Howard et al. 2021, §A.8) usa apenas o lema de Fan, Grama & Liu (2015): exp{λξ − ψ_E(λ)ξ²} ≤ 1 + λξ para ξ ≥ −1 e λ ∈ [0,1). Para o teste unilateral, sob a nula fraca E[d_i | passado] = μ_i ≤ 0, basta a cota <strong>inferior</strong> d_i − γ_i ≥ −c:",
"<strong>The one-sided constant c.</strong> The statement of Choe & Ramdas assumes |d_i − γ_i| ≤ c, which would give c = 2(1+|ε|). The underlying proof (Howard et al. 2021, §A.8) only uses the lemma of Fan, Grama & Liu (2015): exp{λξ − ψ_E(λ)ξ²} ≤ 1 + λξ for ξ ≥ −1 and λ ∈ [0,1). For the one-sided test, under the weak null E[d_i | past] = μ_i ≤ 0, the <strong>lower</strong> bound d_i − γ_i ≥ −c suffices:")}</p>
<div class="math-box">$$¤mathbb E_{{i-1}}¤!¤left[e^{{¤lambda(d_i-¤gamma_i)-¤psi_{{E,c}}(¤lambda)(d_i-¤gamma_i)^2}}¤right]e^{{¤lambda(¤gamma_i-¤mu_i)}} ¤le ¤big(1+¤lambda(¤mu_i-¤gamma_i)¤big)e^{{¤lambda(¤gamma_i-¤mu_i)}}¤le 1 .$$
{T("Como λΣd_i ≤ λΣ(d_i − μ_i), o processo é limitado por uma supermartingala não negativa. Como d_i ≥ −(1+ε) e γ_i ≤ 0, vale", "Since λΣd_i ≤ λΣ(d_i − μ_i), the process is bounded by a non-negative supermartingale. Since d_i ≥ −(1+ε) and γ_i ≤ 0,")} ¤(c = 1+¤max(¤varepsilon,0)¤). {T("A mistura de e-processes é um e-process, e as pausas entre episódios formam uma subsequência previsível.", "A mixture of e-processes is an e-process, and pauses between episodes form a predictable subsequence.")}</div>
<p>{T("Esta observação é uma leitura direta da demonstração publicada, não um resultado novo. Numa simulação de desenvolvimento (400 trajetórias × 5.000 passos, nula no limite) o erro tipo I ficou ≤ 0,025 contra α = 0,05, e o poder subiu de 0,66 (c de dois lados) para 0,77 (§15). A alternativa por apostas com λ previsível (Waudby-Smith & Ramdas 2024) teve mais poder, mas aceitou substitutas quase idênticas da entrada verdadeira e não foi adotada.",
"This observation is a direct reading of the published proof, not a new result. In a development simulation (400 trajectories × 5,000 steps, null at the boundary) the type-I error was ≤ 0.025 against α = 0.05, and power rose from 0.66 (two-sided c) to 0.77 (§15). The betting alternative with predictable λ (Waudby-Smith & Ramdas 2024) had more power but accepted near-identical substitutes of the true input and was not adopted.")}</p>
<h2>5.7 {T("Multiplicidade ao longo do fluxo: níveis tipo e-LOND", "Multiplicity over the stream: e-LOND-type levels")}</h2>
<p>{T("Cada hipótese de mudança recebe, ao ser criada, um nível fixo que depende apenas do número de hipóteses já criadas e de mudanças já aceitas (regra LOND de Javanmard & Montanari 2018, na versão para e-valores de Xu & Ramdas 2024). Isso controla a taxa de mudanças falsas (FDR) ao longo de um fluxo sem fim, com decisões assíncronas:", "Each change hypothesis receives, at creation, a fixed level that depends only on the number of hypotheses already created and of changes already accepted (the LOND rule of Javanmard & Montanari 2018, in the e-value version of Xu & Ramdas 2024). This controls the false change rate (FDR) over an endless stream, with asynchronous decisions:")}</p>
<div class="math-box">$$¤alpha_n = ¤min¤big(¤alpha¤,¤gamma_n¤,(R_n+1),¤;0.5¤big),¤qquad ¤gamma_n = ¤begin{{cases}}1/(2P) & n¤le P¤¤ ¤tfrac12¤,C/¤big((n-P)¤log^2(n-P+1)¤big) & n>P¤end{{cases}},¤qquad ¤text{{{T("aceita se", "accept if")}}}¤;¤log E ¤ge ¤log(1/¤alpha_n),$$
{T("com α = 0,05, P = 2 × (número de unidades) e C tal que Σγ_n ≤ 1. Uma hipótese é <em>persistente</em>: a sua evidência se acumula entre episódios.", "with α = 0.05, P = 2 × (number of units) and C such that Σγ_n ≤ 1. A hypothesis is <em>persistent</em>: its evidence accumulates across episodes.")}</div>
<h2>5.8 {T("Intervalo adaptativo", "Adaptive interval")}</h2>
<p>{T("O intervalo de 90% é um quantil do erro absoluto atualizado por retroalimentação da cobertura, no espírito da inferência conforme adaptativa (Gibbs & Candès 2021): a cada 8 passos, q̂ ← max(0, q̂ + 0,1·σ̂·Σ(erro fora − 0,1)). A mesma regra é aplicada ao erro da saída final (§11). Não há garantia formal de cobertura sob dependência; a cobertura empírica é reportada.", "The 90% interval is a quantile of the absolute error updated by coverage feedback, in the spirit of adaptive conformal inference (Gibbs & Candès 2021): every 8 steps, q̂ ← max(0, q̂ + 0.1·σ̂·Σ(miss − 0.1)). The same rule is applied to the error of the final output (§11). There is no formal coverage guarantee under dependence; empirical coverage is reported.")}</p>""")

    # ------------------------------------------------------------ 6 aggregation theory
    out.append(f"""<h1>6. {toc[5]}</h1>
<p>{T("M1 e M2 são problemas de <strong>previsão com especialistas</strong>: a cada passo há duas previsões disponíveis e é preciso decidir quanto peso dar a cada uma, só com o passado. Três algoritmos da literatura são usados, sem modificação dos seus núcleos; as escolhas da LEBRE são quais perdas eles recebem e como são encadeados.", "M1 and M2 are problems of <strong>prediction with expert advice</strong>: at every step two forecasts are available and one must decide how much weight to give each, using only the past. Three algorithms from the literature are used, without modifying their cores; LEBRE's choices are which losses they receive and how they are chained.")}</p>
<h2>6.1 AdaHedge</h2>
<p>{T("Pesos exponenciais nas perdas acumuladas com taxa de aprendizado ajustada pelos próprios dados (de Rooij et al. 2014): ela é o logaritmo do número de especialistas dividido pela soma acumulada das <em>lacunas de mistura</em> (quanto a perda da mistura excedeu a perda “de mistura” ideal). O arrependimento contra o melhor especialista cresce como a raiz da variação das perdas, e o algoritmo é <strong>invariante a translação e escala</strong> das perdas: não precisa saber a escala do erro, o que permite usar o erro quadrático sem recorte nem normalização.",
"Exponential weights on the cumulative losses with a learning rate tuned by the data themselves (de Rooij et al. 2014): it is the logarithm of the number of experts divided by the cumulative sum of the <em>mixability gaps</em> (how much the loss of the mixture exceeded the ideal “mix” loss). The regret against the best expert grows as the square root of the loss variation, and the algorithm is <strong>invariant to translation and scale</strong> of the losses: it does not need to know the error scale, which allows using the squared error without clipping or normalisation.")}</p>
<div class="math-box">$$w_{{k,t}} = ¤frac{{e^{{-¤eta_t S_{{k,t-1}}}}}}{{¤sum_j e^{{-¤eta_t S_{{j,t-1}}}}}},¤qquad ¤eta_t = ¤frac{{¤ln K}}{{¤Delta_{{t-1}}}},¤qquad ¤Delta_t = ¤Delta_{{t-1}} + ¤Big(¤textstyle¤sum_k w_{{k,t}}¤ell_{{k,t}} + ¤tfrac{{1}}{{¤eta_t}}¤ln¤sum_k w_{{k,t}}e^{{-¤eta_t¤ell_{{k,t}}}}¤Big),$$
{T("com S_k a perda acumulada do especialista k e K = 2. Quando Δ = 0, os pesos seguem o líder.", "with S_k the cumulative loss of expert k and K = 2. When Δ = 0, the weights follow the leader.")}</div>
<h2>6.2 {T("Switch distribution com uma troca", "Switch distribution with one switch")}</h2>
<p>{T("A <em>switch distribution</em> (van Erven, Grünwald & de Rooij 2012) é uma mistura bayesiana sobre sequências de especialistas que permite trocar de especialista ao longo do tempo. A LEBRE usa a versão mais simples: três hipóteses — “sempre R”, “sempre L'” e “R até algum instante, L' depois” —, com prioris iguais e risco de troca 1/(n+1) no instante n. A posterior é atualizada pelas verossimilhanças gaussianas das duas previsões, com variância comum igual ao menor erro quadrático recente das duas (com piso). Ela concentra peso rapidamente na referência quando a parte adaptativa não ajuda, e troca uma vez quando a parte adaptativa passa a ser claramente melhor. Quando toda a massa está de um lado, a atualização direta pode dar 0/0 por <em>underflow</em>; nesse caso a mesma conta é feita em escala logarítmica.",
"The <em>switch distribution</em> (van Erven, Grünwald & de Rooij 2012) is a Bayesian mixture over expert sequences that allows switching expert over time. LEBRE uses the simplest version: three hypotheses — “always R”, “always L'” and “R until some time, L' after” —, with equal priors and switch hazard 1/(n+1) at time n. The posterior is updated by the Gaussian likelihoods of the two forecasts, with a common variance equal to the smaller recent squared error of the two (with a floor). It concentrates weight quickly on the reference when the adaptive part does not help, and switches once when the adaptive part becomes clearly better. When all the mass is on one side, the direct update can give 0/0 by <em>underflow</em>; in that case the same computation is done in log scale.")}</p>
<h2>6.3 {T("(A,B)-Prod: não ficar muito atrás de um especialista de confiança", "(A,B)-Prod: not falling far behind a trusted expert")}</h2>
<p>{T("O (A,B)-Prod (Sani, Neu & Lazaric 2014) combina um algoritmo <em>oportunista</em> A com um algoritmo de <em>confiança</em> B. O peso de B é fixo em 1/2 e o de A é atualizado multiplicativamente pela diferença de perdas; a fração dada a A é s_t. Para perdas em [0, 1], ele garante arrependimento <strong>constante</strong> contra B e da ordem de √(T log log T) contra A, na versão sem horizonte conhecido. Esse tipo de garantia assimétrica — quase nada a perder contra a escolha segura — vem da fronteira de Pareto do arrependimento (Even-Dar et al. 2008; Koolen 2013).",
"(A,B)-Prod (Sani, Neu & Lazaric 2014) combines an <em>opportunistic</em> algorithm A with a <em>trusted</em> algorithm B. B's weight is fixed at 1/2 and A's is updated multiplicatively by the loss difference; the fraction given to A is s_t. For losses in [0, 1], it guarantees <strong>constant</strong> regret against B and of order √(T log log T) against A, in the version without a known horizon. This kind of asymmetric guarantee — almost nothing to lose against the safe choice — comes from the Pareto frontier of regret (Even-Dar et al. 2008; Koolen 2013).")}</p>
<div class="math-box">$$s_t = ¤frac{{¤eta_t w^A_t}}{{¤eta_t w^A_t + w^B/2}},¤qquad w^A_{{t+1}} = w^A_t¤,(1+¤eta_t¤delta_t)^{{¤eta_{{t+1}}/¤eta_t}},¤qquad ¤delta_t = ¤ell^B_t - ¤ell^A_t,¤qquad ¤eta_t = ¤min¤Big(¤tfrac12,¤ ¤sqrt{{1/(1 + ¤textstyle¤sum_{{¤tau ¤lt t}} ¤delta_¤tau^2)}}¤Big).$$</div>
<h2>6.4 {T("O limite das perdas sem limite", "The limit of unbounded losses")}</h2>
<p>{T("O erro quadrático não tem limite superior. As garantias conhecidas para perdas sem limite e de cauda pesada (Cesa-Bianchi, Mansour & Stoltz 2007; Hazan & Kale 2010; Orabona & Pál 2018; Mhammedi, Koolen & van Erven 2019; V'yugin & Trunov 2019; Alquier 2021; Moulin, Esposito & van der Hoeven 2025) valem em unidades da <strong>maior perda de um passo</strong>. Quando um único passo responde por boa parte de todo o erro de uma série — como num choque de câmbio —, nenhum combinador online consegue garantir que acompanha o melhor especialista com folga pequena em relação ao erro total. Esse limite é uma propriedade dos dados, não do algoritmo, e é tratado explicitamente na avaliação (§10, §14).",
"The squared error has no upper bound. The known guarantees for unbounded and heavy-tailed losses (Cesa-Bianchi, Mansour & Stoltz 2007; Hazan & Kale 2010; Orabona & Pál 2018; Mhammedi, Koolen & van Erven 2019; V'yugin & Trunov 2019; Alquier 2021; Moulin, Esposito & van der Hoeven 2025) hold in units of the <strong>largest single-step loss</strong>. When a single step accounts for a large part of a series' whole error — as in an FX shock —, no online combiner can guarantee tracking the best expert with a small slack relative to the total error. This limit is a property of the data, not of the algorithm, and is handled explicitly in the evaluation (§10, §14).")}</p>""")

    # ------------------------------------------------------------ 7 lifecycle
    out.append(f"""<h1>7. {toc[6]}</h1>
{fig(Dg['life'], T('Estados de uma hipótese de mudança. A evidência só é acumulada fora do aquecimento, com alvo observado e fora de quarentena.', 'States of a change hypothesis. Evidence only accrues outside the warm-up, with an observed target and outside quarantine.'))}
<ul><li>{T("<strong>Unidades:</strong> cada entrada (inclui o próprio passado do alvo, padronizado causalmente) e o estado latente do resíduo (dois filtros do erro padronizado, polos 0,8 e 0,95). Até 4 unidades ativas.", "<strong>Units:</strong> each input (including the target's own past, standardised causally) and the residual latent state (two filters of the standardised error, poles 0.8 and 0.95). Up to 4 active units.")}</li>
<li>{T("<strong>Desafiante de uma entrada:</strong> RLS sobre [médias das 5 faixas, atraso de pico, valor atual x_i(t)] — o bloco é julgado líquido do que x_i(t) já carrega. O alvo do RLS é o resíduo que a mudança explicaria.", "<strong>Input challenger:</strong> RLS on [means of the 5 bands, peak lag, current value x_i(t)] — the block is judged net of what x_i(t) already carries. The RLS target is the residual the change would explain.")}</li>
<li>{T("<strong>Episódio:</strong> aquecimento de 250 amostras sem evidência; encerra ao aceitar, pela regra de varredura (soma do episódio ≤ 0 após 100 amostras) ou em 5.000 amostras; a mesma hipótese espera 2.000 passos para voltar. Só um desafiante em aquecimento por vez (controle de pico de custo).", "<strong>Episode:</strong> 250-sample warm-up without evidence; ends on acceptance, by the scan rule (episode sum ≤ 0 after 100 samples) or at 5,000 samples; the same hypothesis waits 2,000 steps before returning. Only one challenger warms up at a time (cost-peak control).")}</li>
<li>{T("<strong>Decisões</strong> a cada 10 passos: aceitar, encerrar, abrir. Prioridade: teste de remoção periódico das unidades ativas; depois a melhor candidata da triagem (unidade ou divisão). Com 4 unidades ativas, a candidata entra por <em>troca</em> com a de menor contribuição.", "<strong>Decisions</strong> every 10 steps: accept, close, open. Priority: periodic removal test of active units; then the best screened candidate (unit or split). With 4 active units, the candidate enters by <em>swap</em> with the one of smallest contribution.")}</li>
<li>{T("<strong>Julgamento na previsão de S</strong>, não na combinação nem na saída final: a pergunta é se a mudança melhora o especialista estrutural. M1 e M2 não participam das decisões de estrutura.", "<strong>Judged on the forecast of S</strong>, not on the combination nor on the final output: the question is whether the change improves the structural expert. M1 and M2 take no part in structural decisions.")}</li></ul>
{fig(G['ev_trace'], T('Exemplo real (série de desenvolvimento: vazão de uma usina hidrelétrica; entrada x0 = vazão defluente da usina a montante; x1 = próprio passado do alvo). Log-evidência dos experimentos (linhas cheias) contra os seus limiares log(1/α_k) (pontilhadas). A entrada x0 é aceita em t ≈ 3.090 e o estado latente do resíduo em t ≈ 4.230; depois disso, remoções e divisões são testadas e encerradas sem evidência.', 'Real example (development series: flow at a hydro plant; input x0 = outflow of the upstream plant; x1 = the target’s own past). Log-evidence of the experiments (solid) against their thresholds log(1/α_k) (dotted). Input x0 is accepted at t ≈ 3,090 and the residual latent state at t ≈ 4,230; afterwards, removals and splits are tested and closed without evidence.'))}
{fig(G['response'], T('Processo sintético declarado (y = 0,8·x0(t−12) + 0,3·média(x1, t−4…t−7) + ruído; x2 irrelevante). Resposta recuperada pelo núcleo (pontos) contra a verdadeira (barras): o atraso 12 de x0 é recuperado com peso 0,81; o efeito distribuído de x1 aparece na faixa [4–7]; x2 não é aceita.', 'Declared synthetic process (y = 0.8·x0(t−12) + 0.3·mean(x1, t−4…t−7) + noise; x2 irrelevant). Response recovered by the core (dots) against the true one (bars): lag 12 of x0 is recovered with weight 0.81; the distributed effect of x1 appears in band [4–7]; x2 is not accepted.'))}""")

    # ------------------------------------------------------------ 8 misadjustment
    ma = B["misadj"]
    orc = [c for c in ma.columns if c.startswith("orac_")]
    med = {mu: float(ma[ma.mu == mu][orc].max(axis=1).median()) for mu in ma.mu.unique()}
    mx = {mu: float(ma[ma.mu == mu][orc].max(axis=1).max()) for mu in ma.mu.unique()}
    acc = {mu: int((ma[ma.mu == mu].accepted != "[]").sum()) for mu in ma.mu.unique()}
    out.append(f"""<h1>8. {toc[7]}</h1>
<p>{T("Um teste de melhora preditiva compara <strong>métodos</strong> (modelo + procedimento de estimação), não modelos — uma distinção conhecida em econometria (Giacomini & White 2006). Durante o desenvolvimento, isso apareceu de forma concreta: com a base de S aprendendo por NLMS com passo 0,1, alvos <strong>sem nenhuma estrutura</strong> tiveram uma mudança aceita em ~20% das execuções. A causa é que o erro de estimação da referência é previsível pelo passado, e um desafiante pode “corrigi-lo”.",
"A test of predictive improvement compares <strong>methods</strong> (model + estimation procedure), not models — a distinction known in econometrics (Giacomini & White 2006). During development, this appeared concretely: with the base of S learning by NLMS with step 0.1, targets <strong>without any structure</strong> had a change accepted in ~20% of the runs. The cause is that the estimation error of the reference is predictable from the past, and a challenger can “correct” it.")}</p>
<div class="math-box">{T("Seja", "Let")} ¤(f^*_t = ¤mathbb E[y_t¤mid¤mathcal F_{{t-1}}]¤), ¤(¤eta_t = f^*_t - S_t¤) {T("(erro de estimação da referência, previsível) e o desafiante", "(estimation error of the reference, predictable) and the challenger")} ¤(G_t = S_t + g_t¤). {T("Para a diferença de perda quadrática normalizada", "For the normalised squared-loss difference")} ¤(¤Delta_t = [(y_t-S_t)^2-(y_t-G_t)^2]/B_t^2¤):
$$¤textbf{{{T("Proposição 1", "Proposition 1")}}}¤quad ¤mathbb E[¤Delta_t¤mid¤mathcal F_{{t-1}}] = ¤frac{{2g_t¤eta_t - g_t^2}}{{B_t^2}} ¤;¤le¤; ¤frac{{¤eta_t^2}}{{B_t^2}},¤quad ¤text{{{T("com igualdade em", "with equality at")}}}¤; g_t=¤eta_t .$$
{T("<em>Demonstração:</em> y − S = ε + η e y − G = ε + η − g; expandindo, a diferença é 2g(ε+η) − g², e E[ε | passado] = 0. ∎", "<em>Proof:</em> y − S = ε + η and y − G = ε + η − g; expanding, the difference is 2g(ε+η) − g², and E[ε | past] = 0. ∎")}
$$¤textbf{{{T("Corolário (garantia exata)", "Corollary (exact guarantee)")}}}¤quad ¤frac1n¤sum_{{i¤le n}}¤frac{{¤eta_i^2}}{{B_i^2}}¤le¤varepsilon¤;¤;¤forall n ¤;¤Rightarrow¤; ¤text{{{T("sob a nula estrutural, a nula do teste vale", "under the structural null, the test null holds")}}}.$$
{T("Para NLMS com desajuste M, isso exige", "For NLMS with misadjustment M, this requires")} ¤(M ¤lesssim 4¤varepsilon¤) {T("(com ε = 0,002: μ ≲ 0,016).", "(with ε = 0.002: μ ≲ 0.016).")}
$$¤textbf{{{T("Proposição 2 (coeficiente fixo)", "Proposition 2 (fixed coefficient)")}}}¤quad ¤text{{{T("melhora média na janela", "mean improvement over the window")}}} ¤le D_u + ¤varepsilon,¤quad D_u = ¤tfrac{{1}}{{|W|}}¤textstyle¤sum_{{i¤in W}} (P_u¤eta_i)^2/B_i^2 - ¤varepsilon ,$$
{T("em que P_u é a projeção de η nos atributos da unidade. <strong>Proposição 3 (critério prático, aproximação):</strong> a log-evidência cresce como n·D²/(2σ_d²); numa série de comprimento T, aceitações falsas são improváveis se", "where P_u is the projection of η on the unit's features. <strong>Proposition 3 (practical criterion, approximation):</strong> log-evidence grows as n·D²/(2σ_d²); on a series of length T, false acceptances are unlikely if")} ¤(D_u ¤lt ¤sigma_d¤sqrt{{2¤log(1/¤alpha_k)/T}}¤).</div>
{fig(G['misadj'], T(f'Verificação em desenvolvimento (120 execuções com alvos sem estrutura, entradas reais). Esquerda: log-evidência do melhor desafiante possível (oráculo de projeção) contra o limiar; aceitações reais em vermelho. Com μ = 0,1 o oráculo cruza o limiar (mediana {n(med[0.1], 1)}) e houve {acc[0.1]}/40 aceitações; com μ = 0,05 (máx. {n(mx[0.05], 1)}) e μ = 0,03, nenhuma. Nas execuções que aceitaram, o oráculo foi medido depois da aceitação e pode ficar baixo (pontos no piso). Direita: desajuste medido e teórico.',
                            f'Development check (120 runs with structureless targets, real inputs). Left: log-evidence of the best possible challenger (projection oracle) against the threshold; actual acceptances in red. With μ = 0.1 the oracle crosses the threshold (median {n(med[0.1], 1)}) and there were {acc[0.1]}/40 acceptances; with μ = 0.05 (max {n(mx[0.05], 1)}) and μ = 0.03, none. In runs that accepted, the oracle was measured after the acceptance and may be low (points at the floor). Right: measured and theoretical misadjustment.'))}
<div class="alert alert-warning">{T("<strong>Leitura honesta:</strong> o núcleo usa μ = 0,05, que está no <strong>regime prático</strong> da Proposição 3 (o desvio da nula existe, ~0,0013, mas é menor que o detectável no comprimento das séries, ~0,0019), e <strong>não</strong> no regime da garantia exata (μ ≲ 0,016). Por isso o controle de mudanças falsas é verificado empiricamente com lotes nulos (0/40 e 0/30 aceitações no desenvolvimento), e não apenas afirmado pela teoria. A observação relaciona-se com Giacomini & White (2006) e, em outro mecanismo, com Han & Qu (2026); não a encontramos formulada explicitamente para esta situação, mas é uma consequência simples de resultados conhecidos.",
"<strong>Honest reading:</strong> the core uses μ = 0.05, which lies in the <strong>practical regime</strong> of Proposition 3 (the deviation from the null exists, ~0.0013, but is smaller than what is detectable within the series length, ~0.0019), and <strong>not</strong> in the exact-guarantee regime (μ ≲ 0.016). Therefore false-change control is checked empirically with null batches (0/40 and 0/30 acceptances in development), not only asserted by theory. The observation relates to Giacomini & White (2006) and, through another mechanism, to Han & Qu (2026); we did not find it stated explicitly for this situation, but it is a simple consequence of known results.")}</div>""")

    # ------------------------------------------------------------ 9 M1
    out.append(f"""<h1>9. {toc[8]}</h1>
<p>{T("<strong>Motivação.</strong> O núcleo estima a dinâmica do alvo (memória) e o efeito das entradas (estrutura) separadamente, com aprendizado barato. Em algumas famílias isso o deixa <strong>abaixo da fronteira precisão × custo</strong>: uma regressão de custo igual ou menor, que estima as duas coisas juntas, erra 5% menos (§17). A M1 acrescenta essa estimação conjunta como um segundo especialista, sem tocar no núcleo.", "<strong>Motivation.</strong> The core estimates the target dynamics (memory) and the input effect (structure) separately, with cheap learning. In some families this leaves it <strong>below the accuracy × cost frontier</strong>: a regression of equal or lower cost, estimating both jointly, errs 5% less (§17). M1 adds that joint estimation as a second expert, without touching the core.")}</p>
<h2>{T("O especialista E", "The expert E")}</h2>
<p>{T("Variáveis: o próprio alvo nas defasagens 1 e 2 e, para cada uma das m = mín(d, 5) entradas de maior correlação absoluta com o alvo (d = número de entradas), as médias nas bandas de defasagem [0], [1], [2–3], [4–7] e [8–15]:", "Variables: the target itself at lags 1 and 2 and, for each of the m = min(d, 5) inputs with the largest absolute correlation with the target (d = number of inputs), the means over the lag bands [0], [1], [2–3], [4–7] and [8–15]:")}</p>
<div class="math-box">$$z_t = ¤big[1,¤ ¤tilde y_{{t-1}},¤ ¤tilde y_{{t-2}},¤ ¤bar x_{{i,b}}(t)¤big]_{{i ¤le m,¤ b ¤le 5}}, ¤qquad k = 3 + 5m, ¤qquad E_t = ¤operatorname{{clip}}¤big(w_t^¤top z_t,¤ L_t ¤pm 2¤max(¤hat¤sigma_L, ¤text{{{T("piso", "floor")}}})¤big)$$</div>
<ul><li>{T("<strong>Seleção das entradas:</strong> médias exponenciais (taxa 0,01, só passado) de x, x², x·y, y e y², atualizadas a cada 8 alvos aprendidos; a seleção é feita depois de 100 alvos e refeita a cada 5.000. As médias e desvios do momento da seleção padronizam as entradas escolhidas e o alvo. Se o conjunto muda, a regressão e a combinação recomeçam.", "<strong>Input selection:</strong> exponential means (rate 0.01, past only) of x, x², x·y, y and y², updated every 8 learned targets; the selection is made after 100 targets and redone every 5,000. The means and deviations at selection time standardise the chosen inputs and the target. If the set changes, the regression and the combination restart.")}</li>
<li>{T("<strong>Entradas ausentes</strong> são trocadas pelo último valor visto (0 antes do primeiro).", "<strong>Missing inputs</strong> are replaced by the last value seen (0 before the first).")}</li>
<li>{T("<strong>Pesos:</strong> mínimos quadrados recursivos com esquecimento λ = 0,999 e P₀ = 100·I, atualizados a cada 8 alvos aprendidos (fora de quarentena e com entradas dentro do contrato); a matriz é simetrizada a cada atualização e reiniciada se perder a definição positiva. E só existe depois de k atualizações (regressão determinada).", "<strong>Weights:</strong> recursive least squares with forgetting λ = 0.999 and P₀ = 100·I, updated every 8 learned targets (outside quarantine and with inputs within the contract); the matrix is symmetrised at every update and reset if it loses positive definiteness. E only exists after k updates (determined regression).")}</li>
<li>{T("<strong>Recorte:</strong> E fica em L ± 2·máx(σ̂<sub>L</sub>, piso), com σ̂<sub>L</sub> o erro quadrático médio recente do núcleo (média exponencial, taxa 0,01) e o piso de 0,1 vez a escala lenta do alvo; isso limita o estrago de uma regressão mal condicionada.", "<strong>Clip:</strong> E stays within L ± 2·max(σ̂<sub>L</sub>, floor), with σ̂<sub>L</sub> the recent root mean squared error of the core (exponential mean, rate 0.01) and the floor 0.1 times the slow scale of the target; this bounds the damage of an ill-conditioned regression.")}</li></ul>
<h2>{T("A combinação com o núcleo", "The combination with the core")}</h2>
<p>{T("AdaHedge (§6.1) com dois especialistas, L e E, sobre o <strong>erro quadrático sem recorte nem normalização</strong>: os pesos seguem o erro quadrático acumulado, que é o que o erro quadrático médio mede, e a taxa de aprendizado se ajusta sozinha à escala. A combinação observa todo alvo observado em que E existe. <strong>Entrada em sombra:</strong> até 100 atualizações, L' = L.", "AdaHedge (§6.1) with two experts, L and E, on the <strong>squared error without clipping or normalisation</strong>: the weights follow the accumulated squared error, which is what the mean squared error measures, and the learning rate adapts to the scale by itself. The combination observes every observed target at which E exists. <strong>Shadow entry:</strong> until 100 updates, L' = L.")}</p>
<div class="math-box">$$L'_t = (1 - ¤omega_t)¤,L_t + ¤omega_t¤,E_t, ¤qquad ¤omega_t = ¤frac{{e^{{-¤eta_t S^E_{{t-1}}}}}}{{e^{{-¤eta_t S^L_{{t-1}}}} + e^{{-¤eta_t S^E_{{t-1}}}}}}, ¤qquad S^¤bullet_{{t-1}} = ¤sum_{{¤tau ¤lt t}} (y_¤tau - ¤bullet_¤tau)^2$$</div>
<p>{T("<strong>Por que AdaHedge e não um (A,B)-Prod:</strong> o Prod exige perdas em [0, 1]. Três formas de pôr o erro quadrático nesse intervalo foram medidas e falharam por razões diferentes (§17): recortar em 2σ deixa o Prod cego aos erros grandes; dividir pelo maior erro já visto o congela depois de um recorde; dividir pelo maior erro recente dá peso pequeno aos passos de erro grande, justamente onde o especialista ganha. Trocar a garantia constante do Prod pela do AdaHedge (arrependimento que, relativo ao erro total, some com o tamanho da série) foi o que funcionou.",
"<strong>Why AdaHedge and not an (A,B)-Prod:</strong> Prod needs losses in [0, 1]. Three ways of putting the squared error into that interval were measured and failed for different reasons (§17): clipping at 2σ leaves Prod blind to large errors; dividing by the largest error ever seen freezes it after a record; dividing by the largest recent error gives small weight to the large-error steps, exactly where the expert gains. Trading Prod's constant guarantee for AdaHedge's (a regret that, relative to the total error, vanishes with series length) is what worked.")}</p>""")

    # ------------------------------------------------------------ 10 M2
    top = sh["top"]
    out.append(f"""<h1>10. {toc[9]}</h1>
<p>{T("<strong>Motivação.</strong> Em séries quase imprevisíveis (por exemplo, retornos e níveis de câmbio), uma parte adaptativa pode errar mais que prever zero ou repetir o último valor: ela aprende ruído. A M2 faz a saída partir de uma <strong>referência trivial R</strong> declarada com os dados — zero para variações como retornos financeiros, sazonal ingênuo (o valor de um ciclo atrás) quando há ciclo, persistência (o último valor) nos demais casos — e só passar a confiar em L' quando ele se mostra melhor. Enquanto R não está definida (antes de um ciclo completo, no caso sazonal), a saída é L'.",
"<strong>Motivation.</strong> In nearly unpredictable series (for example, FX returns and levels), an adaptive part may err more than predicting zero or repeating the last value: it learns noise. M2 makes the output start from a <strong>trivial reference R</strong> declared with the data — zero for changes such as financial returns, seasonal naive (the value one cycle ago) when there is a cycle, persistence (the last value) otherwise — and only come to trust L' when it proves better. While R is undefined (before a full cycle, in the seasonal case), the output is L'.")}</p>
<ul>
<li>{T("<strong>H</strong> — AdaHedge entre R e L' sobre o erro quadrático (§6.1): confiança, sem trocas.", "<strong>H</strong> — AdaHedge between R and L' on the squared error (§6.1): confidence, no switches.")}</li>
<li>{T("<strong>W</strong> — troca num só sentido, de R para L' (§6.2), sobre perdas gaussianas (y − ·)²/2s², com s² = máx(mín(σ̂²<sub>R</sub>, σ̂²<sub>L'</sub>), piso²) e σ̂² médias exponenciais (taxa 0,01) dos erros quadráticos de cada lado, só do passado.", "<strong>W</strong> — one-way switch from R to L' (§6.2), on Gaussian losses (y − ·)²/2s², with s² = max(min(σ̂²<sub>R</sub>, σ̂²<sub>L'</sub>), floor²) and σ̂² exponential means (rate 0.01) of each side's squared errors, past only.")}</li>
<li>{T("<strong>Combinação</strong> — (A,B)-Prod sem horizonte (§6.3) com B = H (confiança) e A = W (oportunista); as perdas são (y − ·)²/N_t, com N_t = máx(perdas do passo, 0,99·N_{t−1}) — o maior erro recente, com esquecimento, para pôr as perdas em [0, 1] sem congelar depois de um recorde.", "<strong>Combination</strong> — horizon-free (A,B)-Prod (§6.3) with B = H (confidence) and A = W (opportunist); the losses are (y − ·)²/N_t, with N_t = max(step losses, 0.99·N_{t−1}) — the largest recent error, with forgetting, to put the losses into [0, 1] without freezing after a record.")}</li>
<li>{T("H, W e o Prod só aprendem nos passos com alvo observado, fora de quarentena do alvo e com R definida.", "H, W and Prod only learn on steps with an observed target, outside target quarantine and with R defined.")}</li></ul>
<div class="math-box">$$¤hat y_t = s_t¤,W_t + (1 - s_t)¤,H_t, ¤qquad H_t = w^H_{{R,t}}R_t + w^H_{{L',t}}L'_t, ¤qquad W_t = w^W_{{R,t}}R_t + w^W_{{L',t}}L'_t$$</div>
<p>{T("<strong>Auditoria da porta.</strong> Em paralelo, um e-process (§5.6) com orçamento próprio α = 0,01 e margem ε = 0,002 testa se a parte adaptativa melhora a referência vigente (e, depois de uma troca, o contrário); cada aceitação é registrada como evento e a hipótese é recriada. Esse teste <strong>não decide a saída</strong>: ele só documenta quando a evidência mudou de lado, com o mesmo tipo de garantia das mudanças de estrutura.", "<strong>Gate audit.</strong> In parallel, an e-process (§5.6) with its own budget α = 0.01 and margin ε = 0.002 tests whether the adaptive part improves on the current reference (and, after a switch, the opposite); each acceptance is logged as an event and the hypothesis is recreated. This test <strong>does not decide the output</strong>: it only documents when the evidence changed sides, with the same kind of guarantee as the structural changes.")}</p>
<h2>{T("Garantias e o limite dos choques", "Guarantees and the limit of shocks")}</h2>
<p>{T("Para as perdas normalizadas, o Prod garante arrependimento constante contra H e da ordem de √(T log log T) contra W; na escala original não há limite formal limpo, porque a normalização muda com o tempo. O limite da §6.4 aparece nos dados: em séries financeiras um único dia pode responder por boa parte de todo o erro (nas", "For the normalised losses, Prod guarantees constant regret against H and of order √(T log log T) against W; in the original scale there is no clean formal bound, because the normalisation changes over time. The limit of §6.4 shows up in the data: in financial series a single day can account for much of the whole error (in the")} {sh['n']} {T("séries de desenvolvimento medidas,", "development series measured,")} {sh['over5']} {T("têm o maior passo acima de 5% do erro total da referência; o maior,", "have the largest step above 5% of the reference's total error; the largest,")} {top[0][1]}, {n(100 * top[0][2], 1)}%). {T("Por isso a régua de avaliação trata essas séries como indecidíveis (§14).", "That is why the evaluation ruler treats those series as undecidable (§14).")}</p>""")

    # ------------------------------------------------------------ 11 safeguards
    out.append(f"""<h1>11. {toc[10]}</h1>
<p>{T("Duas salvaguardas atuam no caminho da saída do núcleo e custam ~15 operações por passo. Ambas são práticas padrão de engenharia; entram aqui porque a sua ausência produziu a falha mais grave observada (§15).", "Two safeguards act on the output path of the core and cost ~15 operations per step. Both are standard engineering practice; they are here because their absence produced the most severe failure observed (§15).")}</p>
<ul><li>{T("<strong>Retenção durante lacunas do alvo:</strong> a memória recebe o último valor observado, nunca a própria previsão. Sem isso, a memória fica em malha aberta e, com certos pesos aprendidos, a recursão é instável (raiz característica ~1,75 num caso real).", "<strong>Hold during target gaps:</strong> the memory receives the last observed value, never its own forecast. Without this, the memory runs open-loop and, with some learned weights, the recursion is unstable (characteristic root ~1.75 in a real case).")}</li>
<li>{T("<strong>Contrato de saída:</strong> a previsão do núcleo é limitada ao envelope dos alvos observados (máximo e mínimo correntes que relaxam para a média lenta à taxa 10⁻³), alargado em 0,5× a sua largura; uma previsão não finita vira o último valor observado.", "<strong>Output contract:</strong> the core forecast is limited to the envelope of observed targets (running maximum and minimum relaxing toward the slow mean at rate 10⁻³), widened by 0.5× its width; a non-finite forecast becomes the last observed value.")}</li>
<li>{T("<strong>M1 e M2 herdam a contenção:</strong> E fica a no máximo 2·máx(σ̂<sub>L</sub>, piso) de L; R é um valor já observado (ou zero); toda saída de M1 e M2 é média ponderada de previsões contidas. Uma perda não finita nunca entra nos pesos.", "<strong>M1 and M2 inherit the containment:</strong> E stays at most 2·max(σ̂<sub>L</sub>, floor) from L; R is an already observed value (or zero); every output of M1 and M2 is a weighted mean of contained forecasts. A non-finite loss never enters the weights.")}</li></ul>
{fig(G['stress'], T('Teste de estresse do núcleo no desenvolvimento: quatro lacunas artificiais no alvo (24, 100, 400 e 1.500 passos) em 29 séries. Desvio máximo da previsão em relação à amplitude observada. Pelo critério declarado antes do teste (desvio > 10×, previsão não finita ou erro > 1,5× o da mesma série sem lacunas) foram 10, 2 e 2 séries; as duas restantes com a correção são uma série curta (1.024 passos) em que as lacunas cobrem quase toda a região de teste, com desvio < 0,4 da amplitude.', 'Stress test of the core in development: four artificial target gaps (24, 100, 400 and 1,500 steps) on 29 series. Maximum deviation of the forecast relative to the observed range. By the criterion declared before the test (deviation > 10×, non-finite forecast or error > 1.5× that of the same series without gaps) there were 10, 2 and 2 series; the two remaining with the fix are a short series (1,024 steps) where the gaps cover almost the whole test region, with deviation < 0.4 of the range.'))}
<h2>{T("Intervalo da saída", "Output interval")}</h2>
<p>{T("A saída final ŷ vem com um intervalo de 90% calculado pela regra da §5.8 aplicada ao erro de ŷ (início em 1,645 vezes o erro quadrático médio recente). A cobertura do intervalo do núcleo foi medida nas avaliações próprias do núcleo (§13); a cobertura do intervalo da saída completa <strong>não foi reportada</strong> na avaliação final.", "The final output ŷ comes with a 90% interval computed by the rule of §5.8 applied to the error of ŷ (starting at 1.645 times the recent root mean squared error). The coverage of the core interval was measured in the core's own evaluations (§13); the coverage of the complete output interval <strong>was not reported</strong> in the final evaluation.")}</p>""")

    # ------------------------------------------------------------ 12 cost
    bd = dev["breakdown"]
    out.append(f"""<h1>12. {toc[11]}</h1>
<p>{T("O custo é contado operação a operação no código (somas, produtos, divisões, raízes, exponenciais e logaritmos contam 1 FP), por componente. O custo por passo é <strong>quase fixo</strong>: memória, base, triagem, M1 e M2 rodam sempre; os experimentos do núcleo acrescentam custo apenas quando há vaga ocupada, e os picos ocorrem nos passos de decisão. Nada cresce com o tempo.", "Cost is counted operation by operation in the code (additions, products, divisions, roots, exponentials and logarithms count 1 FP), per component. The per-step cost is <strong>almost fixed</strong>: memory, base, screening, M1 and M2 always run; the core's experiments add cost only when a slot is busy, and peaks occur at decision steps. Nothing grows with time.")}</p>
<h2>{T("Núcleo", "Core")}</h2>
<p>{T(f"O núcleo foi desenhado com um contrato de média ≤ 400 e máximo ≤ 1.000 FP por passo nas séries reais. Na sua avaliação pré-registrada própria (60 séries), a média foi {n(fp3, 0)} e o máximo {n(fpmax3, 0)}: o contrato <strong>não foi cumprido</strong> por {n(100 * (fp3 / 400 - 1), 1)}% na média e {n(100 * (fpmax3 / 1000 - 1), 1)}% no pico, e não foi revisado depois do resultado. Na avaliação final da LEBRE, o núcleo custou mediana de {n(cc_med, 0)} FP por passo.",
f"The core was designed with a contract of mean ≤ 400 and maximum ≤ 1,000 FP per step on real series. In its own pre-registered evaluation (60 series), the mean was {n(fp3, 0)} and the maximum {n(fpmax3, 0)}: the contract <strong>was not met</strong>, by {n(100 * (fp3 / 400 - 1), 1)}% in the mean and {n(100 * (fpmax3 / 1000 - 1), 1)}% in the peak, and it was not revised after the result. In LEBRE's final evaluation, the core cost a median of {n(cc_med, 0)} FP per step.")}</p>
<h2>M1 + M2</h2>
<p>{T("A contagem de M1 e M2 foi auditada: a implementação faz exatamente as contas declaradas (cada par da matriz da RLS simetrizado uma vez; só a linha nova das entradas padronizada), com as previsões idênticas às validadas em", "The count of M1 and M2 was audited: the implementation performs exactly the declared operations (each pair of the RLS matrix symmetrised once; only the new input row standardised), with forecasts identical to the validated ones in")} {dev['identity'][0]} {T("de", "of")} {dev['identity'][1]} {T("séries; a auditoria elevou a contagem em", "series; the audit raised the count by")} {n(100 * (dev['audit_median'] - 1), 1)}% ({T("mediana", "median")}). {T("Por atualização da RLS: 6k² + 5k (a cada 8 alvos); previsão do especialista: 2k + 18m + 4; AdaHedge: 48; M2: ~132 a 137.", "Per RLS update: 6k² + 5k (every 8 targets); expert prediction: 2k + 18m + 4; AdaHedge: 48; M2: ~132 to 137.")}</p>
{tbl([T("Parte", "Part"), T("FP por passo (mediana, uma série por família do desenvolvimento, antes da auditoria)", "FP per step (median, one series per development family, before the audit)")],
     [(T("núcleo", "core"), n(bd['v052'], 0)), ("M2", n(bd['m2'], 0)), (T("M1: atualização da RLS", "M1: RLS update"), n(bd['m1_rls'], 0)), (T("M1: resto", "M1: rest"), n(bd['m1_rest'], 0)), ("<strong>Total</strong>", f"<strong>{n(bd['total'], 0)}</strong>")])}
<p>{T(f"<strong>Teto de custo de M1 + M2.</strong> A meta preliminar de desenho (custo total ≤ 1,25 vez o do núcleo) mostrou-se incompatível com M1 + M2: com o núcleo em ~450 FP, o acréscimo máximo seria ~110 FP, menos que a M2 sozinha. Antes da avaliação final, o responsável pelo projeto a substituiu por um teto de <strong>acréscimo absoluto de 1.100 FP por passo</strong> em cada série (o custo novo é quase fixo; uma razão puniria as séries em que o núcleo é barato), mais 2,5 vezes o custo do núcleo nas famílias abaixo da fronteira. No desenvolvimento ({dev['identity'][1]} séries) o acréscimo teve mediana de {n(dev['inc_median'], 0)} e máximo de {n(dev['inc_max'], 0)} FP; na avaliação final, mediana de {n(inc_med, 0)} e máximo de {n(inc_max, 0)} FP, com custo total entre {n(c_min, 0)} e {n(c_max, 0)} FP.",
f"<strong>Cost ceiling of M1 + M2.</strong> The preliminary design target (total cost ≤ 1.25 times that of the core) proved incompatible with M1 + M2: with the core at ~450 FP, the maximum increment would be ~110 FP, less than M2 alone. Before the final evaluation, the project owner replaced it with a ceiling of an <strong>absolute increment of 1,100 FP per step</strong> on every series (the new cost is nearly fixed; a ratio would penalise the series where the core is cheap), plus 2.5 times the core's cost on the families below the frontier. In development ({dev['identity'][1]} series) the increment had a median of {n(dev['inc_median'], 0)} and a maximum of {n(dev['inc_max'], 0)} FP; in the final evaluation, a median of {n(inc_med, 0)} and a maximum of {n(inc_max, 0)} FP, with total cost between {n(c_min, 0)} and {n(c_max, 0)} FP.")}</p>
{fig(G['cost_gain'], T("Avaliação final: acréscimo de custo de M1 + M2 e razão de erro LEBRE ÷ núcleo, por série. O custo é pago em todas as séries; o ganho aparece em bacias e câmbio.", "Final evaluation: cost increment of M1 + M2 and error ratio LEBRE ÷ core, per series. The cost is paid on every series; the gain appears in basins and FX."))}
<h2>{T("Memória", "Memory")}</h2>
<p>{T(f"O estado tem tamanho fixo, dados o número de entradas e os períodos. O estado do núcleo foi medido no porte em C (capacidades para até 8 entradas e 160 hipóteses): {n(core_bytes, 0)} bytes; a maior parte é a tabela de hipóteses, que pode ser reduzida. M1 e M2 guardam {n(nm, 0)} números (k = {F['ram_info']['k']} no pior caso: {F['ram_info']['numeros_m1']} na M1, {F['ram_info']['numeros_m2']} na M2), {n(8 * nm, 0)} bytes em precisão dupla. Total <strong>estimado</strong>: {n(F['ram'], 0)} bytes ({n(F['ram'] / 1024, 1)} KB), dentro do limite pré-registrado de 128 KB; M1 e M2 não foram portados nem medidos.",
f"The state has a fixed size, given the number of inputs and the periods. The core state was measured in the C port (capacities for up to 8 inputs and 160 hypotheses): {n(core_bytes, 0)} bytes; most of it is the hypothesis table, which can be reduced. M1 and M2 hold {n(nm, 0)} numbers (k = {F['ram_info']['k']} in the worst case: {F['ram_info']['numeros_m1']} in M1, {F['ram_info']['numeros_m2']} in M2), {n(8 * nm, 0)} bytes in double precision. Total <strong>estimated</strong>: {n(F['ram'], 0)} bytes ({n(F['ram'] / 1024, 1)} KB), within the pre-registered limit of 128 KB; M1 and M2 were not ported nor measured.")}</p>""")

    # ------------------------------------------------------------ 13 observability
    A = B["ex"]["A"]; r3cov = float(r3m.coverage.mean())
    grpA = A["groups"]
    evA = [e for e in A["events"] if e[1] == "accepted"]
    out.append(f"""<h1>13. {toc[12]}</h1>
<p>{T("Cada previsão pode ser decomposta em parcelas nomeadas: no núcleo, memória, base e cada bloco ativo; depois, o peso ω da M1 e, na M2, os pesos de R e L' em H e em W e a fração s_t. Cada mudança de estrutura e cada aceitação da auditoria da porta ficam registradas. Exemplo de uma série de desenvolvimento do núcleo:", "Each forecast can be decomposed into named contributions: in the core, memory, base and each active block; then, M1's weight ω and, in M2, the weights of R and L' in H and in W and the fraction s_t. Every structural change and every acceptance of the gate audit is logged. Example from a core development series:")}</p>
{tbl([T('Instante', 'Time'), T('Evento', 'Event'), T('Mudança', 'Change'), 'log E', T('Amostras de evidência', 'Evidence samples')],
     [(n(e[0], 0), T('aceita', 'accepted'), (T('acrescentar entrada x0', 'add input x0') if "'in'" in e[3] else T('acrescentar estado latente do resíduo', 'add residual latent state')), n(e[5], 2), n(e[6], 0)) for e in evA])}
<ul><li>{T("<strong>Grupos equivalentes:</strong> junto da entrada aceita x0 o modelo reporta o grupo", "<strong>Equivalent groups:</strong> together with the accepted input x0 the model reports the group")} {{{', '.join('x' + str(i) for i in grpA.get("('in', 0)", []))}}} {T("(correlação causal ≥ 0,95 entre x0, a vazão defluente da usina a montante, e x1, o próprio passado do alvo). A afirmação é “esta entrada ou uma equivalente”.", "(causal correlation ≥ 0.95 between x0, the outflow of the upstream plant, and x1, the target's own past). The claim is “this input or an equivalent one”.")}</li>
<li>{T("<strong>Intervalo de 90% do núcleo:</strong> cobertura empírica de", "<strong>90% interval of the core:</strong> empirical coverage of")} {n(A['coverage'], 3)} {T("nesta série e", "on this series and")} {n(r3cov, 3)} {T("em média nas 60 séries da avaliação própria do núcleo.", "on average over the 60 series of the core's own evaluation.")}</li>
<li>{T("<strong>Registro de experimentos encerrados:</strong> cada teste que não passou fica registrado com a sua evidência (por exemplo, testes de remoção de x0 com log E entre −1,8 e −3,2: a entrada continua útil).", "<strong>Log of closed experiments:</strong> each test that did not pass is logged with its evidence (for instance, removal tests of x0 with log E between −1.8 and −3.2: the input remains useful).")}</li>
<li>{T("<strong>M1 e M2:</strong> o peso final ω da M1 é lido por série (§19: ω = 0 em todas as séries de solar, eólica e carga); quais entradas a M1 escolheu também fica disponível.", "<strong>M1 and M2:</strong> M1's final weight ω is read per series (§19: ω = 0 on every solar, wind and load series); which inputs M1 chose is also available.")}</li></ul>
{fig(G['forecast'], T('Janela de 400 passos da mesma série: valor observado, previsão do núcleo e intervalo de 90%.', 'A 400-step window of the same series: observed value, core forecast and 90% interval.'))}""")

    # ------------------------------------------------------------ 14 methodology
    out.append(f"""<div class="page-break"></div><h1>14. {toc[13]}</h1>
<p>{T("Duas perguntas foram avaliadas com protocolos próprios, ambos pré-registrados: (a) o núcleo é competitivo na sua classe de orçamento? (b) M1 e M2 melhoram o núcleo sem piorar nenhum domínio?", "Two questions were evaluated with their own protocols, both pre-registered: (a) is the core competitive within its budget class? (b) do M1 and M2 improve the core without harming any domain?")}</p>
<h2>{T("Disciplina comum", "Common discipline")}</h2>
<ul><li>{T("<strong>Previsão online de um passo</strong>, sem olhar o futuro; todos os modelos recebem as mesmas entradas, padronizadas de forma causal.", "<strong>Online one-step forecasting</strong>, without looking ahead; all models receive the same inputs, standardised causally.")}</li>
<li>{T("<strong>Pré-registro:</strong> antes de cada acesso a dados reservados, um documento fixou perguntas, métricas, comparadores, critérios e os hashes do código; cada reserva foi executada uma única vez; o carregador de dados impede o acesso às reservas fora de uma execução pré-registrada. Incidentes de infraestrutura (sem alteração de modelo) estão descritos junto dos resultados.", "<strong>Pre-registration:</strong> before each access to reserved data, a document fixed questions, metrics, comparators, criteria and the code hashes; each reserve was run a single time; the data loader blocks access to the reserves outside a pre-registered run. Infrastructure incidents (without any model change) are described with the results.")}</li>
<li>{T("<strong>Divisão das séries</strong> por permutações com semente fixa, antes de qualquer modelagem; cada conjunto de validação foi escolhido só por metadados, congelado com SHA-256 e usado uma vez.", "<strong>Series split</strong> by fixed-seed permutations, before any modelling; each validation set was chosen from metadata only, frozen with SHA-256 and used once.")}</li></ul>
<h2>{T("(a) O núcleo na classe de orçamento", "(a) The core in the budget class")}</h2>
<ul><li>{T("<strong>Métrica:</strong> erro quadrático médio na região de teste (últimos 70% de cada série, alvo observado), dividido pelo do NLinear online calibrado na mesma série; média geométrica entre séries; IC 95% por bootstrap estratificado por domínio (2.000 reamostragens). <strong>Falha catastrófica:</strong> erro relativo > 10, desvio > 10× a amplitude observada ou previsão não finita.", "<strong>Metric:</strong> mean squared error on the test region (last 70% of each series, observed target), divided by that of the calibrated online NLinear on the same series; geometric mean across series; 95% CI by bootstrap stratified by domain (2,000 resamples). <strong>Catastrophic failure:</strong> relative error > 10, deviation > 10× the observed range, or a non-finite forecast.")}</li>
<li>{T("<strong>Dados:</strong> vazões e geração do Operador Nacional do Sistema Elétrico (ONS; usinas em cascata), bacias do CAMELS-BR (Chagas et al. 2020; precipitação, evapotranspiração, temperatura) e medidores do Building Data Genome 2 (Miller et al. 2020; clima), mais dois benchmarks de identificação de sistemas no desenvolvimento.", "<strong>Data:</strong> flows and generation from the Brazilian National Grid Operator (ONS; cascaded plants), CAMELS-BR basins (Chagas et al. 2020; precipitation, evapotranspiration, temperature) and Building Data Genome 2 meters (Miller et al. 2020; weather), plus two system-identification benchmarks in development.")}</li>
<li>{T("<strong>Modelos de fundação</strong> (caros demais para rodar em todos os passos): avaliados em 1.000 pontos por série, os mesmos para todos, com o mesmo contexto e as entradas atuais como covariáveis futuras conhecidas. <strong>Comparadores ajustados em lote</strong> (SARIMAX com entradas, FITS, SparseTSF, ajuste fino do TTM): ajustados nos primeiros 15% da série (até 5.000 pontos), depois com pesos fixos.", "<strong>Foundation models</strong> (too expensive to run at every step): evaluated on 1,000 points per series, the same for all, with the same context and the current inputs as known future covariates. <strong>Batch-fitted comparators</strong> (SARIMAX with inputs, FITS, SparseTSF, TTM fine-tuning): fitted on the first 15% of the series (up to 5,000 points), then with fixed weights.")}</li></ul>
{tbl([T('Conjunto', 'Set'), T('Séries', 'Series'), T('Uso', 'Use')],
     [(T('Desenvolvimento', 'Development'), '29 (ONS 11, CAMELS 10, BDG2 5, Silverbox, Cascaded Tanks ×2)', T('todo o desenho e ajuste do núcleo', 'all design and tuning of the core')),
      (T('Reserva 1', 'Reserve 1'), '125 (ONS 45, CAMELS 50, BDG2 30)', T('revelou a falha das lacunas (§15)', 'revealed the gap failure (§15)')),
      (T('Reserva 2', 'Reserve 2'), '40 (CAMELS 20, BDG2 20)', T('verificou a correção', 'checked the fix')),
      (T('Reserva 3', 'Reserve 3'), '60 (CAMELS 30, BDG2 30)', T('comparadores ultraleves, TTM, porte em C, microcontrolador', 'ultralight comparators, TTM, C port, microcontroller'))])}
<h2>{T("(b) M1 e M2 contra o núcleo", "(b) M1 and M2 against the core")}</h2>
<p>{T("Os dados da avaliação final foram reservados em 05/10/2026, antes de qualquer código de M1 e M2, com hashes e travas. A métrica é a razão de erros quadráticos médios LEBRE ÷ núcleo, série a série. <strong>Régua por decidibilidade:</strong> cada série é classificada pelo IC 95% de núcleo ÷ R (bootstrap de blocos pareado, 2.000 réplicas) como “núcleo melhor”, “referência melhor” ou “indecidível”. Critérios: (1) nas “referência melhor”, LEBRE ÷ R com limite superior ≤ 1,01; (2) nas “núcleo melhor”, LEBRE ÷ núcleo com limite superior ≤ 1,02; (4) nos testes negativos, nenhuma entrada falsa a mais que o núcleo; (6) a estrutura do núcleo preservada; (7) nas séries curtas (360 passos), ≤ 1,05 do melhor entre núcleo e R. <strong>Adendos do choque</strong> (decididos durante o desenvolvimento, antes da validação 5 e da avaliação final): uma série em que o maior passo isolado passa de máx(5%, 5·2 ln(n)/n) do erro de R fica indecidível nos critérios 1 e 2 (n = passos avaliados), porque nela nenhum combinador tem garantia útil (§6.4).",
"The final-evaluation data were reserved on 2026-10-05, before any M1 and M2 code, with hashes and locks. The metric is the mean-squared-error ratio LEBRE ÷ core, series by series. <strong>Decidability ruler:</strong> each series is classified by the 95% CI of core ÷ R (paired block bootstrap, 2,000 replicates) as “core better”, “reference better” or “undecidable”. Criteria: (1) on “reference better”, LEBRE ÷ R with upper limit ≤ 1.01; (2) on “core better”, LEBRE ÷ core with upper limit ≤ 1.02; (4) on negative tests, no more false inputs than the core; (6) the core's structure preserved; (7) on short series (360 steps), ≤ 1.05 of the best of core and R. <strong>Shock addenda</strong> (decided during development, before validation 5 and the final evaluation): a series whose largest single step exceeds max(5%, 5·2 ln(n)/n) of R's error is undecidable on criteria 1 and 2 (n = evaluated steps), because on it no combiner has a useful guarantee (§6.4).")}</p>
<p>{T("<strong>F6</strong>, nas famílias em que o núcleo está abaixo da fronteira precisão × custo: custo ≤ 2,5 vezes o do núcleo e erro ≤ 1,05 vez o menor erro entre as 8 regressões do diagnóstico com custo ≤ o da LEBRE. <strong>Promoção</strong> (pré-registro; decisões do responsável pelo projeto): (A) nenhuma piora por família, (B) LEBRE ÷ núcleo em todas as séries com limite superior do IC 95% abaixo de 1 e (C) memória estimada ≤ 128 KB.",
"<strong>F6</strong>, on the families where the core lies below the accuracy × cost frontier: cost ≤ 2.5 times that of the core and error ≤ 1.05 times the lowest error among the diagnostic's 8 regressions with cost ≤ that of LEBRE. <strong>Promotion</strong> (pre-registration; project-owner decisions): (A) no harm per family, (B) LEBRE ÷ core over all series with the upper limit of the 95% CI below 1 and (C) estimated memory ≤ 128 KB.")}</p>""")

    # ------------------------------------------------------------ 15 core evidence
    out.append(f"""<div class="page-break"></div><h1>15. {toc[14]}</h1>
<p>{T("O núcleo foi desenvolvido e avaliado antes de M1 e M2 existirem, com o protocolo (a) da §14. Como M1 e M2 não alteram nenhuma decisão do núcleo (estrutura idêntica verificada em todas as séries do desenvolvimento, das validações e da avaliação final), essas evidências continuam valendo para o núcleo dentro da LEBRE.", "The core was developed and evaluated before M1 and M2 existed, with protocol (a) of §14. Since M1 and M2 do not alter any decision of the core (identical structure verified on every series of development, validations and the final evaluation), this evidence still holds for the core within LEBRE.")}</p>
<h2>15.1 {T("Desenvolvimento: validade e descoberta", "Development: validity and discovery")}</h2>
{fig(G['eproc'], T('Simulação do e-process (400 trajetórias × 5.000 passos). Esquerda: erro tipo I sob três formas de incremento (recortado, dois pontos, cauda pesada) na nula no limite, contra α = 0,05. Direita: poder e tempo mediano até o limiar para uma melhora de +0,0072 por amostra. A variante adotada é a de c unilateral.', 'E-process simulation (400 trajectories × 5,000 steps). Left: type-I error under three increment shapes (clipped, two-point, heavy tail) at the null boundary, against α = 0.05. Right: power and median time to the threshold for an improvement of +0.0072 per sample. The adopted variant is the one-sided c.'))}
{tbl([T('Situação', 'Situation'), T('Resultado (desenvolvimento)', 'Result (development)')],
     [(T('Sintéticos com entradas brancas (atrasos até 12)', 'Synthetic with white inputs (delays up to 12)'), T('estrutura recuperada até o atraso exato em 500–2.200 passos (ex.: atraso 12, peso 0,84 contra 0,80)', 'structure recovered to the exact delay in 500–2,200 steps (e.g. delay 12, weight 0.84 vs 0.80)')),
      (T('Semi-sintéticos (entradas reais, efeito conhecido)', 'Semi-synthetic (real inputs, known effect)'), T('entrada verdadeira (ou do seu grupo) em 2 de 3 tarefas estruturadas, 3/3 sementes; latência 4–17 mil passos', 'true input (or its group) in 2 of 3 structured tasks, 3/3 seeds; latency 4–17 thousand steps')),
      (T('Entradas muito suaves (autocorrelação ~0,99), atraso médio/longo', 'Very smooth inputs (autocorrelation ~0.99), medium/long delay'), T('<strong>não descobertas</strong>; um oráculo online (conhece o atraso, testa desde o início) precisa de 9–27 mil passos ou nunca chega em 32 mil', '<strong>not discovered</strong>; an online oracle (knows the delay, tests from the start) needs 9–27 thousand steps or never gets there in 32 thousand')),
      (T('Alvos sem estrutura (lotes nulos com entradas reais)', 'Structureless targets (null batches with real inputs)'), T('0/40 e 0/30 aceitações; 0 entradas exógenas falsas em todos os conjuntos declarados', '0/40 and 0/30 acceptances; 0 false exogenous inputs in all declared sets')),
      (T('Entradas quase idênticas (correlação 0,98)', 'Near-identical inputs (correlation 0.98)'), T('indistinguíveis por melhora preditiva; o modelo reporta o grupo', 'indistinguishable by predictive improvement; the model reports the group'))])}
<p>{T("O limite em entradas suaves é conhecido em princípio: com regressores muito persistentes, a informação nova de um atraso além do valor atual é pequena (Stambaugh 1999; Campbell & Yogo 2006). Nesses casos, a previsão continua boa porque a base já usa o valor atual das entradas; o que se perde é a <em>explicação</em> do atraso.", "The limit on smooth inputs is known in principle: with very persistent regressors, the new information of a delay beyond the current value is small (Stambaugh 1999; Campbell & Yogo 2006). In those cases the forecast remains good because the base already uses the current input values; what is lost is the <em>explanation</em> of the delay.")}</p>
<h2>15.2 {T("Controle de mudanças falsas em simulação com dependência", "False-change control in simulation with dependence")}</h2>
<p>{T(f"O núcleo congelado foi rodado em {len(fr)} execuções sintéticas (plano e critério declarados antes; 4 entradas correlacionadas entre si, persistência 0,5 ou 0,95, 30 mil passos): quatro nulos (ruído branco; alvo autorregressivo; ruído cuja variância depende de uma entrada; quebra de variância) e três cenários com uma entrada verdadeira com atraso 6 (simples; com uma isca de correlação 0,7 com a verdadeira; com ruído autorregressivo de cauda pesada).",
f"The frozen core was run in {len(fr)} synthetic runs (plan and criterion declared beforehand; 4 mutually correlated inputs, persistence 0.5 or 0.95, 30 thousand steps): four nulls (white noise; autoregressive target; noise whose variance depends on an input; variance break) and three scenarios with one true input at delay 6 (plain; with a decoy of correlation 0.7 with the true one; with heavy-tailed autoregressive noise).")}</p>
{fig(G['fdr'], T('Em cima: fração de execuções com pelo menos uma mudança falsa (IC 95% de Clopper-Pearson) e fração em que a mudança falsa ainda estava no modelo no fim (traço). Embaixo: taxa estimada de mudanças falsas (FDR) com limite superior de bootstrap. Azul: nulos; laranja: cenários com uma entrada verdadeira.', 'Top: fraction of runs with at least one false change (Clopper-Pearson 95% CI) and fraction where the false change was still in the model at the end (dash). Bottom: estimated false change rate (FDR) with bootstrap upper bound. Blue: nulls; orange: scenarios with one true input.'))}
<ul><li>{T(f"<strong>Nulos:</strong> {v_null} de {n_null} execuções com qualquer mudança aceita.", f"<strong>Nulls:</strong> {v_null} of {n_null} runs with any accepted change.")}</li>
<li>{T(f"<strong>Com uma entrada verdadeira:</strong> pelo critério declarado (por cenário, 100 execuções) os três cenários ficaram dentro de α = 0,05 (FDR {n(fall.loc['P2', 'FDR'])} e {n(fall.loc['P3', 'FDR'])} nos piores). Mas, com persistência 0,5, duas células passaram de 0,05: FDR {n(fcell('P2', 0.5).FDR)} (isca) e {n(fcell('P3', 0.5).FDR)} (ruído dependente), com {int(fcell('P2', 0.5)['runs_V>0'])}/50 e {int(fcell('P3', 0.5)['runs_V>0'])}/50 execuções afetadas.",
                  f"<strong>With one true input:</strong> by the declared criterion (per scenario, 100 runs) the three scenarios stayed within α = 0.05 (FDR {n(fall.loc['P2', 'FDR'])} and {n(fall.loc['P3', 'FDR'])} in the worst). But, with persistence 0.5, two cells exceeded 0.05: FDR {n(fcell('P2', 0.5).FDR)} (decoy) and {n(fcell('P3', 0.5).FDR)} (dependent noise), with {int(fcell('P2', 0.5)['runs_V>0'])}/50 and {int(fcell('P3', 0.5)['runs_V>0'])}/50 runs affected.")}</li>
<li>{T(f"<strong>Mecanismo:</strong> em todas as {n_prox} execuções afetadas, a mudança falsa foi uma entrada <em>correlacionada</em> com a verdadeira, aceita antes dela. Enquanto a verdadeira não está no modelo, essa substituta melhora de fato a previsão da referência — o teste acerta a pergunta que faz, mas a resposta não é estrutural. O teste periódico de remoção retirou a substituta em {n_rem} dos {n_prox} casos; em {n_fin} de {len(fr)} execuções ela ficou no modelo final.",
                  f"<strong>Mechanism:</strong> in all {n_prox} affected runs, the false change was an input <em>correlated</em> with the true one, accepted before it. While the true input is not in the model, this substitute does improve the reference forecast — the test answers its own question correctly, but the answer is not structural. The periodic removal test took the substitute out in {n_rem} of the {n_prox} cases; in {n_fin} of {len(fr)} runs it stayed in the final model.")}</li></ul>
<div class="alert alert-warning">{T("<strong>O que isto permite afirmar:</strong> nos cenários simulados, o procedimento controlou empiricamente as falsas <em>melhoras preditivas</em> e não aceitou nada em alvos sem estrutura. Ele <strong>não</strong> garante estrutura verdadeira: com entradas correlacionadas, uma substituta pode ser aceita e, às vezes, permanecer. Uma entrada aceita significa “melhorou a previsão da referência vigente, com evidência”, não “é a causa”.",
"<strong>What this allows us to claim:</strong> in the simulated scenarios, the procedure empirically controlled false <em>predictive improvements</em> and accepted nothing on structureless targets. It does <strong>not</strong> guarantee true structure: with correlated inputs, a substitute may be accepted and sometimes remain. An accepted input means “it improved the forecast of the current reference, with evidence”, not “it is the cause”.")}</div>""")

    out.append(f"""<h2>15.3 {T("Avaliações em séries nunca vistas", "Evaluations on never-seen series")}</h2>
<p>{T(f"<strong>Reserva 1 (125 séries): uma falha de engenharia.</strong> A primeira avaliação pré-registrada, com o núcleo ainda sem as salvaguardas de saída, revelou que <strong>6 de 125 séries explodiam</strong> (erro relativo de 13 até 10⁷⁹): quando o alvo faltava por muitos passos, a memória preenchia o próprio histórico com as próprias previsões. O resultado pré-registrado ficou dominado por essas séries (média geométrica {n(t1.loc['V052_COMPLETA', 'ALL'], 2)}); numa vista exploratória, não pré-registrada, sem as 6 séries, o erro relativo foi 0,706, igual ao do desenvolvimento. A falha motivou as salvaguardas da §11, verificadas no desenvolvimento e depois em séries nunca vistas.",
f"<strong>Reserve 1 (125 series): an engineering failure.</strong> The first pre-registered evaluation, with the core still without the output safeguards, revealed that <strong>6 of 125 series exploded</strong> (relative error from 13 up to 10⁷⁹): when the target was missing for many steps, the memory filled its own history with its own forecasts. The pre-registered result was dominated by these series (geometric mean {n(t1.loc['V052_COMPLETA', 'ALL'], 2)}); in an exploratory view, not pre-registered, without the 6 series, the relative error was 0.706, equal to development. The failure motivated the safeguards of §11, checked in development and then on never-seen series.")}</p>
{fig(G['bar_r3'], T('Reserva 3 (60 séries nunca vistas). Média geométrica do erro quadrático relativo ao NLinear online, com IC 95%. Azul: núcleo da LEBRE; cinza: outros modelos da classe de orçamento; laranja: referências clássicas.', 'Reserve 3 (60 never-seen series). Geometric mean of the squared error relative to online NLinear, with 95% CI. Blue: LEBRE core; grey: other budget-class models; orange: classical references.'))}
{tbl([T('Modelo', 'Model'), 'CAMELS', 'BDG2', T('Todas [IC 95%]', 'All [95% CI]'), T('Séries > 1,5', 'Series > 1.5'), T('Catastróficas', 'Catastrophic'), T('Operações/previsão', 'Operations/forecast')],
     [(f"<strong>{mn[m]}</strong>" if m == 'V052_PY' else mn[m], n(t3.loc[m, 'CAMELS']), n(t3.loc[m, 'BDG2']), f"{n(t3.loc[m, 'ALL'])} {ci_s(t3.loc[m, 'CI95'])}",
       f"{t3.loc[m, 'share>1.5'] * 100:.0f}%", int(t3.loc[m, 'catastrophic']), (n(t3.loc[m, 'FLOPs'], 0) if t3.loc[m, 'FLOPs'] == t3.loc[m, 'FLOPs'] else T('ajuste por MV', 'ML fit')))
      for m in ['V052_PY', 'NLINEAR_ONLINE', 'DLINEAR_ONLINE', 'HOLT_WINTERS', 'FITS', 'ARX_NLMS', 'LASSO_ONLINE', 'V051', 'SPARSETSF', 'AIRLINE_X', 'ARX_RLS_PLS']],
     hl=lambda r: r[0].startswith('<strong>'))}
{tbl([T('Teto (1.000 pontos)', 'Ceiling (1,000 points)'), 'CAMELS', 'BDG2', T('Todas', 'All'), T('Razão pareada núcleo/modelo [IC 95%]', 'Paired ratio core/model [95% CI]'), T('Operações/previsão', 'Operations/forecast')],
     [(mn[m], n(g1[m]['camels']), n(g1[m]['bdg2']), n(g1[m]['ALL']), f"{n(pf[m]['ratio'])} [{n(pf[m]['lo'])}; {n(pf[m]['hi'])}]", fl)
      for m, fl in [('AIRLINE_X', T('ajuste por MV', 'ML fit')), ('TTM_ZS', f"{n(ttm0 / 1e6, 1)}·10⁶"), ('TTM_FT_EXOG', f"{n(ttm1 / 1e6, 1)}·10⁶"), ('CHRONOS2_COV', '~10⁹–10¹⁰')]])}
<div class="alert alert-info">{T(f"<strong>Resumo das avaliações do núcleo com as salvaguardas:</strong> erro relativo ao NLinear de {n(t2.loc['V052_CORRIGIDA', 'ALL'])} (reserva 2, 40 séries) e {n(t3.loc['V052_PY', 'ALL'])} (reserva 3, 60 séries); nenhuma série catastrófica e nenhuma acima de 1,5 nas 100 séries; empate com o SARIMAX com entradas nas duas (razões pareadas {n(B['r2_pair']['AIRLINE_X']['ratio'])} e {n(p3['AIRLINE_X']['ratio'])}); erro menor que o do TTM sem treino e ajustado; erro 16% e 25% acima do Chronos-2 com covariáveis. Os ultraleves FITS e SparseTSF, ajustados em lote nos primeiros 15%, ficaram atrás do NLinear online neste regime de um passo, para o qual não foram desenhados. O intervalo de 90% teve cobertura empírica de 0,905 e {n(r3cov, 3)}.",
f"<strong>Summary of the core evaluations with the safeguards:</strong> error relative to NLinear of {n(t2.loc['V052_CORRIGIDA', 'ALL'])} (reserve 2, 40 series) and {n(t3.loc['V052_PY', 'ALL'])} (reserve 3, 60 series); no catastrophic series and none above 1.5 among the 100 series; a tie with SARIMAX with inputs in both (paired ratios {n(B['r2_pair']['AIRLINE_X']['ratio'])} and {n(p3['AIRLINE_X']['ratio'])}); lower error than TTM zero-shot and fine-tuned; error 16% and 25% above Chronos-2 with covariates. The ultralight FITS and SparseTSF, batch-fitted on the first 15%, were behind online NLinear in this one-step regime, for which they were not designed. The 90% interval had empirical coverage of 0.905 and {n(r3cov, 3)}.")}</div>""")

