{tbl([T('Série', 'Series'), T('Origem', 'Source'), T('Entradas', 'Inputs'), T('Média', 'Mean'), T('Mediana', 'Median'), 'p99,9' if P else 'p99.9', T('Pico', 'Peak'), T('Tempo', 'Time'), 'NMSE', T('Mudanças', 'Changes')], rows_m)}
