      (T('Núcleo: tudo ligado, sem testes', 'Core: all on, no tests'), T('todas as entradas e o estado latente ativos desde o início', 'all inputs and the latent state active from the start'), T(f"reservas 2 e 3 (100 séries): razão {n(ab['ratio'])} [{n(ab['lo'])}; {n(ab['hi'])}], custo ~5% menor — exploratório; <strong>o mecanismo de testes não melhora a precisão</strong> de forma distinguível", f"reserves 2 and 3 (100 series): ratio {n(ab['ratio'])} [{n(ab['lo'])}; {n(ab['hi'])}], ~5% lower cost — exploratory; <strong>the testing mechanism does not improve accuracy</strong> distinguishably")),
      (T('Núcleo sem divisões hierárquicas', 'Core without hierarchical splits'), T('a resposta fica nas faixas de oitava + pico', 'the response stays at octave bands + peak'), T('razão 0,996 [0,988; 1,001] — sem diferença em dados reais', 'ratio 0.996 [0.988; 1.001] — no difference on real data')),
      (T('Hipótese por atraso (“atômica”)', 'Per-lag hypothesis (“atomic”)'), T('uma hipótese por atraso de cada entrada (~400 hipóteses)', 'one hypothesis per lag of each input (~400 hypotheses)'), T('desenvolvimento: 0,757 contra 0,645 (1.000 pontos); descoberta mais lenta', 'development: 0.757 vs 0.645 (1,000 points); slower discovery')),
