           T("<strong>Comparadores ausentes:</strong> um ARMAX com filtro de Kalman online e um SARIMAX com parâmetros atualizados online.", "<strong>Missing comparators:</strong> an online ARMAX with a Kalman filter and a SARIMAX with online parameter updates."),
           T("<strong>Intervalo:</strong> cobertura empírica perto de 90% no núcleo, sem garantia formal; não reportada para a saída completa.", "<strong>Interval:</strong> empirical coverage near 90% in the core, without a formal guarantee; not reported for the complete output."),
