                (T('Combinação e saída', 'Combination and output'), T('λ = 0,99, η = 0,5, a cada 8 passos; envelope com taxa 10⁻³ e margem 0,5×', 'λ = 0.99, η = 0.5, every 8 steps; envelope with rate 10⁻³ and margin 0.5×')),
