             ("M1", T("bandas", "bands"), "[0], [1], [2–3], [4–7], [8–15]", T("médias; + alvo nas defasagens 1 e 2; k = 3 + 5m", "means; + target at lags 1 and 2; k = 3 + 5m")),
             ("M1", "RLS", "λ = 0,999; δ = 100" if P else "λ = 0.999; δ = 100", T("a cada 8 alvos aprendidos; E só depois de k atualizações", "every 8 learned targets; E only after k updates")),
